121	    public static boolean rename(final File file, final String newName) {
122	        // file is null then return false
123	        if (file == null) return false;
124	        // file doesn't exist then return false
125	        if (!file.exists()) return false;
126	        // the new name is space then return false
127	        if (UtilsBridge.isSpace(newName)) return false;
128	        // the new name equals old name then return true
129	        if (newName.equals(file.getName())) return true;
130	        File newFile = new File(file.getParent() + File.separator + newName);
131	        // the new name of file exists then return false
132	        return !newFile.exists()
133	                && file.renameTo(newFile);
134	    }
