498	    /**
499	     * Delete the directory.
500	     *
501	     * @param dir The directory.
502	     * @return {@code true}: success<br>{@code false}: fail
503	     */
504	    private static boolean deleteDir(final File dir) {
505	        if (dir == null) return false;
506	        // dir doesn't exist then return true
507	        if (!dir.exists()) return true;
508	        // dir isn't a directory then return false
509	        if (!dir.isDirectory()) return false;
510	        File[] files = dir.listFiles();
511	        if (files != null && files.length > 0) {
512	            for (File file : files) {
513	                if (file.isFile()) {
514	                    if (!file.delete()) return false;
515	                } else if (file.isDirectory()) {
516	                    if (!deleteDir(file)) return false;
517	                }
518	            }
519	        }
520	        return dir.delete();
521	    }
