601	     */
602	    public static boolean deleteFilesInDirWithFilter(final File dir, final FileFilter filter) {
603	        if (dir == null || filter == null) return false;
604	        // dir doesn't exist then return true
605	        if (!dir.exists()) return true;
606	        // dir isn't a directory then return false
607	        if (!dir.isDirectory()) return false;
608	        File[] files = dir.listFiles();
609	        if (files != null && files.length != 0) {
610	            for (File file : files) {
611	                if (filter.accept(file)) {
612	                    if (file.isFile()) {
613	                        if (!file.delete()) return false;
614	                    } else if (file.isDirectory()) {
615	                        if (!deleteDir(file)) return false;
616	                    }
617	                }
618	            }
619	        }
620	        return true;
621	    }
