947	    public static boolean isUtf8(final File file) {
948	        if (file == null) return false;
949	        InputStream is = null;
950	        try {
951	            byte[] bytes = new byte[24];
952	            is = new BufferedInputStream(new FileInputStream(file));
953	            int read = is.read(bytes);
954	            if (read != -1) {
955	                byte[] readArr = new byte[read];
956	                System.arraycopy(bytes, 0, readArr, 0, read);
957	                return isUtf8(readArr) == 100;
958	            } else {
959	                return false;
960	            }
961	        } catch (IOException e) {
962	            e.printStackTrace();
963	        } finally {
964	            try {
965	                if (is != null) {
966	                    is.close();
967	                }
