1417	        long totalSize;
1418	        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.JELLY_BEAN_MR2) {
1419	            blockSize = statFs.getBlockSizeLong();
1420	            totalSize = statFs.getBlockCountLong();
1421	        } else {
1422	            blockSize = statFs.getBlockSize();
1423	            totalSize = statFs.getBlockCount();
1424	        }
1425	        return blockSize * totalSize;
1426	    }
