424	    /**
425	     * Return type of network.
426	     * <p>Must hold {@code <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />}</p>
427	     *
428	     * @return type of network
429	     * <ul>
430	     * <li>{@link NetworkUtils.NetworkType#NETWORK_ETHERNET} </li>
431	     * <li>{@link NetworkUtils.NetworkType#NETWORK_WIFI    } </li>
432	     * <li>{@link NetworkUtils.NetworkType#NETWORK_4G      } </li>
433	     * <li>{@link NetworkUtils.NetworkType#NETWORK_3G      } </li>
434	     * <li>{@link NetworkUtils.NetworkType#NETWORK_2G      } </li>
435	     * <li>{@link NetworkUtils.NetworkType#NETWORK_UNKNOWN } </li>
436	     * <li>{@link NetworkUtils.NetworkType#NETWORK_NO      } </li>
437	     * </ul>
438	     */
439	    @RequiresPermission(ACCESS_NETWORK_STATE)
440	    public static NetworkType getNetworkType() {
441	        if (isEthernet()) {
442	            return NetworkType.NETWORK_ETHERNET;
443	        }
444	        NetworkInfo info = getActiveNetworkInfo();
445	        if (info != null && info.isAvailable()) {
446	            if (info.getType() == ConnectivityManager.TYPE_WIFI) {
447	                return NetworkType.NETWORK_WIFI;
448	            } else if (info.getType() == ConnectivityManager.TYPE_MOBILE) {
449	                switch (info.getSubtype()) {
450	                    case TelephonyManager.NETWORK_TYPE_GSM:
451	                    case TelephonyManager.NETWORK_TYPE_GPRS:
452	                    case TelephonyManager.NETWORK_TYPE_CDMA:
453	                    case TelephonyManager.NETWORK_TYPE_EDGE:
454	                    case TelephonyManager.NETWORK_TYPE_1xRTT:
455	                    case TelephonyManager.NETWORK_TYPE_IDEN:
456	                        return NetworkType.NETWORK_2G;
457	
458	                    case TelephonyManager.NETWORK_TYPE_TD_SCDMA:
459	                    case TelephonyManager.NETWORK_TYPE_EVDO_A:
460	                    case TelephonyManager.NETWORK_TYPE_UMTS:
461	                    case TelephonyManager.NETWORK_TYPE_EVDO_0:
462	                    case TelephonyManager.NETWORK_TYPE_HSDPA:
463	                    case TelephonyManager.NETWORK_TYPE_HSUPA:
464	                    case TelephonyManager.NETWORK_TYPE_HSPA:
465	                    case TelephonyManager.NETWORK_TYPE_EVDO_B:
466	                    case TelephonyManager.NETWORK_TYPE_EHRPD:
467	                    case TelephonyManager.NETWORK_TYPE_HSPAP:
468	                        return NetworkType.NETWORK_3G;
469	
470	                    case TelephonyManager.NETWORK_TYPE_IWLAN:
471	                    case TelephonyManager.NETWORK_TYPE_LTE:
472	                        return NetworkType.NETWORK_4G;
473	
474	                    case TelephonyManager.NETWORK_TYPE_NR:
475	                        return NetworkType.NETWORK_5G;
476	                    default:
477	                        String subtypeName = info.getSubtypeName();
478	                        if (subtypeName.equalsIgnoreCase("TD-SCDMA")
479	                                || subtypeName.equalsIgnoreCase("WCDMA")
480	                                || subtypeName.equalsIgnoreCase("CDMA2000")) {
481	                            return NetworkType.NETWORK_3G;
482	                        } else {
483	                            return NetworkType.NETWORK_UNKNOWN;
484	                        }
485	                }
486	            } else {
487	                return NetworkType.NETWORK_UNKNOWN;
488	            }
489	        }
490	        return NetworkType.NETWORK_NO;
491	    }
