540	     * Return the ip address.
541	     * <p>Must hold {@code <uses-permission android:name="android.permission.INTERNET" />}</p>
542	     *
543	     * @param useIPv4 True to use ipv4, false otherwise.
544	     * @return the ip address
545	     */
546	    @RequiresPermission(INTERNET)
547	    public static String getIPAddress(final boolean useIPv4) {
548	        try {
549	            Enumeration<NetworkInterface> nis = NetworkInterface.getNetworkInterfaces();
550	            LinkedList<InetAddress> adds = new LinkedList<>();
551	            while (nis.hasMoreElements()) {
552	                NetworkInterface ni = nis.nextElement();
553	                // To prevent phone of xiaomi return "10.0.2.15"
554	                if (!ni.isUp() || ni.isLoopback()) continue;
555	                Enumeration<InetAddress> addresses = ni.getInetAddresses();
556	                while (addresses.hasMoreElements()) {
557	                    adds.addFirst(addresses.nextElement());
558	                }
559	            }
560	            for (InetAddress add : adds) {
561	                if (!add.isLoopbackAddress()) {
562	                    String hostAddress = add.getHostAddress();
563	                    boolean isIPv4 = hostAddress.indexOf(':') < 0;
564	                    if (useIPv4) {
565	                        if (isIPv4) return hostAddress;
566	                    } else {
567	                        if (!isIPv4) {
568	                            int index = hostAddress.indexOf('%');
569	                            return index < 0
570	                                    ? hostAddress.toUpperCase()
571	                                    : hostAddress.substring(0, index).toUpperCase();
572	                        }
573	                    }
574	                }
575	            }
576	        } catch (SocketException e) {
577	            e.printStackTrace();
578	        }
579	        return "";
580	    }
