840	    private static boolean isSameScanResults(List<ScanResult> l1, List<ScanResult> l2) {
841	        if (l1 == null && l2 == null) {
842	            return true;
843	        }
844	        if (l1 == null || l2 == null) {
845	            return false;
846	        }
847	        if (l1.size() != l2.size()) {
848	            return false;
849	        }
850	        for (int i = 0; i < l1.size(); i++) {
851	            ScanResult r1 = l1.get(i);
852	            ScanResult r2 = l2.get(i);
853	            if (!isSameScanResultContent(r1, r2)) {
854	                return false;
855	            }
856	        }
857	        return true;
858	    }
859	
860	    private static boolean isSameScanResultContent(ScanResult r1, ScanResult r2) {
861	        return r1 != null && r2 != null && UtilsBridge.equals(r1.BSSID, r2.BSSID)
862	                && UtilsBridge.equals(r1.SSID, r2.SSID)
863	                && UtilsBridge.equals(r1.capabilities, r2.capabilities)
864	                && r1.level == r2.level;
865	    }
