876	        @RequiresPermission(ACCESS_NETWORK_STATE)
877	        void registerListener(final OnNetworkStatusChangedListener listener) {
878	            if (listener == null) return;
879	            UtilsBridge.runOnUiThread(new Runnable() {
880	                @Override
881	                @RequiresPermission(ACCESS_NETWORK_STATE)
882	                public void run() {
883	                    int preSize = mListeners.size();
884	                    mListeners.add(listener);
885	                    if (preSize == 0 && mListeners.size() == 1) {
886	                        mType = getNetworkType();
887	                        IntentFilter intentFilter = new IntentFilter(ConnectivityManager.CONNECTIVITY_ACTION);
888	                        Utils.getApp().registerReceiver(NetworkChangedReceiver.getInstance(), intentFilter);
889	                    }
890	                }
891	            });
892	        }
