894	        boolean isRegistered(final OnNetworkStatusChangedListener listener) {
895	            if (listener == null) return false;
896	            return mListeners.contains(listener);
897	        }
898	
899	        void unregisterListener(final OnNetworkStatusChangedListener listener) {
900	            if (listener == null) return;
901	            UtilsBridge.runOnUiThread(new Runnable() {
902	                @Override
903	                public void run() {
904	                    int preSize = mListeners.size();
905	                    mListeners.remove(listener);
906	                    if (preSize == 1 && mListeners.size() == 0) {
907	                        Utils.getApp().unregisterReceiver(NetworkChangedReceiver.getInstance());
908	                    }
909	                }
910	            });
911	        }
