913	        @Override
914	        public void onReceive(Context context, Intent intent) {
915	            if (ConnectivityManager.CONNECTIVITY_ACTION.equals(intent.getAction())) {
916	                // debouncing
917	                UtilsBridge.runOnUiThreadDelayed(new Runnable() {
918	                    @Override
919	                    @RequiresPermission(ACCESS_NETWORK_STATE)
920	                    public void run() {
921	                        NetworkType networkType = NetworkUtils.getNetworkType();
922	                        if (mType == networkType) return;
923	                        mType = networkType;
924	                        if (networkType == NetworkType.NETWORK_NO) {
925	                            for (OnNetworkStatusChangedListener listener : mListeners) {
926	                                listener.onDisconnected();
927	                            }
928	                        } else {
929	                            for (OnNetworkStatusChangedListener listener : mListeners) {
930	                                listener.onConnected(networkType);
931	                            }
932	                        }
933	                    }
934	                }, 1000);
935	            }
936	        }
937	
938	        private static class LazyHolder {
939	            private static final NetworkChangedReceiver INSTANCE = new NetworkChangedReceiver();
940	        }
941	    }
