1023	    public static final class WifiScanResults {
1024	
1025	        private List<ScanResult> allResults    = new ArrayList<>();
1026	        private List<ScanResult> filterResults = new ArrayList<>();
1027	
1028	        public WifiScanResults() {
1029	        }
1030	
1031	        public List<ScanResult> getAllResults() {
1032	            return allResults;
1033	        }
1034	
1035	        public List<ScanResult> getFilterResults() {
1036	            return filterResults;
1037	        }
1038	
1039	        public void setAllResults(List<ScanResult> allResults) {
1040	            this.allResults = allResults;
1041	            filterResults = filterScanResult(allResults);
1042	        }
1043	
1044	        private static List<ScanResult> filterScanResult(final List<ScanResult> results) {
1045	            if (results == null || results.isEmpty()) {
1046	                return new ArrayList<>();
1047	            }
1048	            LinkedHashMap<String, ScanResult> map = new LinkedHashMap<>(results.size());
1049	            for (ScanResult result : results) {
1050	                if (TextUtils.isEmpty(result.SSID)) {
1051	                    continue;
1052	                }
1053	                ScanResult resultInMap = map.get(result.SSID);
1054	                if (resultInMap != null && resultInMap.level >= result.level) {
1055	                    continue;
1056	                }
1057	                map.put(result.SSID, result);
1058	            }
1059	            return new ArrayList<>(map.values());
1060	        }
1061	
1062	    }
