1168	    public abstract static class Task<T> implements Runnable {
1169	
1170	        private static final int NEW         = 0;
1171	        private static final int RUNNING     = 1;
1172	        private static final int EXCEPTIONAL = 2;
1173	        private static final int COMPLETING  = 3;
1174	        private static final int CANCELLED   = 4;
1175	        private static final int INTERRUPTED = 5;
1176	        private static final int TIMEOUT     = 6;
1177	
1178	        private final AtomicInteger state = new AtomicInteger(NEW);
1179	
1180	        private volatile boolean isSchedule;
1181	        private volatile Thread  runner;
1182	
1183	        private Timer             mTimer;
1184	        private long              mTimeoutMillis;
1185	        private OnTimeoutListener mTimeoutListener;
1186	
1187	        private Executor deliver;
1188	
1189	        public abstract T doInBackground() throws Throwable;
1190	
1191	        public abstract void onSuccess(T result);
1192	
1193	        public abstract void onCancel();
1194	
1195	        public abstract void onFail(Throwable t);
1196	
1197	        @Override
1198	        public void run() {
1199	            if (isSchedule) {
1200	                if (runner == null) {
1201	                    if (!state.compareAndSet(NEW, RUNNING)) return;
1202	                    runner = Thread.currentThread();
1203	                    if (mTimeoutListener != null) {
1204	                        Log.w("ThreadUtils", "Scheduled task doesn't support timeout.");
1205	                    }
1206	                } else {
1207	                    if (state.get() != RUNNING) return;
1208	                }
1209	            } else {
1210	                if (!state.compareAndSet(NEW, RUNNING)) return;
1211	                runner = Thread.currentThread();
1212	                if (mTimeoutListener != null) {
1213	                    mTimer = new Timer();
1214	                    mTimer.schedule(new TimerTask() {
1215	                        @Override
1216	                        public void run() {
1217	                            if (!isDone() && mTimeoutListener != null) {
1218	                                timeout();
1219	                                mTimeoutListener.onTimeout();
1220	                                onDone();
1221	                            }
1222	                        }
1223	                    }, mTimeoutMillis);
1224	                }
1225	            }
1226	            try {
1227	                final T result = doInBackground();
1228	                if (isSchedule) {
1229	                    if (state.get() != RUNNING) return;
1230	                    getDeliver().execute(new Runnable() {
1231	                        @Override
1232	                        public void run() {
1233	                            onSuccess(result);
1234	                        }
1235	                    });
1236	                } else {
1237	                    if (!state.compareAndSet(RUNNING, COMPLETING)) return;
1238	                    getDeliver().execute(new Runnable() {
1239	                        @Override
1240	                        public void run() {
1241	                            onSuccess(result);
1242	                            onDone();
1243	                        }
1244	                    });
1245	                }
1246	            } catch (InterruptedException ignore) {
1247	                state.compareAndSet(CANCELLED, INTERRUPTED);
1248	            } catch (final Throwable throwable) {
1249	                if (!state.compareAndSet(RUNNING, EXCEPTIONAL)) return;
1250	                getDeliver().execute(new Runnable() {
1251	                    @Override
1252	                    public void run() {
1253	                        onFail(throwable);
1254	                        onDone();
1255	                    }
1256	                });
1257	            }
1258	        }
1259	
1260	        public void cancel() {
1261	            cancel(true);
1262	        }
1263	
1264	        public void cancel(boolean mayInterruptIfRunning) {
1265	            synchronized (state) {
1266	                if (state.get() > RUNNING) return;
1267	                state.set(CANCELLED);
1268	            }
1269	            if (mayInterruptIfRunning) {
1270	                if (runner != null) {
1271	                    runner.interrupt();
1272	                }
1273	            }
1274	
1275	            getDeliver().execute(new Runnable() {
1276	                @Override
1277	                public void run() {
1278	                    onCancel();
1279	                    onDone();
1280	                }
1281	            });
1282	        }
1283	
1284	        private void timeout() {
1285	            synchronized (state) {
1286	                if (state.get() > RUNNING) return;
1287	                state.set(TIMEOUT);
1288	            }
1289	            if (runner != null) {
1290	                runner.interrupt();
1291	            }
1292	        }
1293	
1294	
1295	        public boolean isCanceled() {
1296	            return state.get() >= CANCELLED;
1297	        }
1298	
1299	        public boolean isDone() {
1300	            return state.get() > RUNNING;
1301	        }
1302	
1303	        public Task<T> setDeliver(Executor deliver) {
1304	            this.deliver = deliver;
1305	            return this;
1306	        }
1307	
1308	        /**
1309	         * Scheduled task doesn't support timeout.
1310	         */
1311	        public Task<T> setTimeout(final long timeoutMillis, final OnTimeoutListener listener) {
1312	            mTimeoutMillis = timeoutMillis;
1313	            mTimeoutListener = listener;
1314	            return this;
1315	        }
1316	
1317	        private void setSchedule(boolean isSchedule) {
1318	            this.isSchedule = isSchedule;
1319	        }
1320	
1321	        private Executor getDeliver() {
1322	            if (deliver == null) {
1323	                return getGlobalDeliver();
1324	            }
1325	            return deliver;
1326	        }
1327	
1328	        @CallSuper
1329	        protected void onDone() {
1330	            TASK_POOL_MAP.remove(this);
1331	            if (mTimer != null) {
1332	                mTimer.cancel();
1333	                mTimer = null;
1334	                mTimeoutListener = null;
1335	            }
1336	        }
1337	
1338	        public interface OnTimeoutListener {
1339	            void onTimeout();
1340	        }
1341	    }
