1343	    public static class SyncValue<T> {
1344	
1345	        private CountDownLatch mLatch = new CountDownLatch(1);
1346	        private AtomicBoolean  mFlag  = new AtomicBoolean();
1347	        private T              mValue;
1348	
1349	        public void setValue(T value) {
1350	            if (mFlag.compareAndSet(false, true)) {
1351	                mValue = value;
1352	                mLatch.countDown();
1353	            }
1354	        }
1355	
1356	        public T getValue() {
1357	            if (!mFlag.get()) {
1358	                try {
1359	                    mLatch.await();
1360	                } catch (InterruptedException e) {
1361	                    e.printStackTrace();
1362	                }
1363	            }
1364	            return mValue;
1365	        }
1366	
1367	        public T getValue(long timeout, TimeUnit unit, T defaultValue) {
1368	            if (!mFlag.get()) {
1369	                try {
1370	                    mLatch.await(timeout, unit);
1371	                } catch (InterruptedException e) {
1372	                    e.printStackTrace();
1373	                    return defaultValue;
1374	                }
1375	            }
1376	            return mValue;
1377	        }
1378	    }
