1380	    private static Executor getGlobalDeliver() {
1381	        if (sDeliver == null) {
1382	            sDeliver = new Executor() {
1383	                @Override
1384	                public void execute(@NonNull Runnable command) {
1385	                    runOnUiThread(command);
1386	                }
1387	            };
1388	        }
1389	        return sDeliver;
1390	    }

