509	    private static IToast newToast(ToastUtils toastUtils) {
510	        if (!toastUtils.isNotUseSystemToast) {
511	            if (NotificationManagerCompat.from(Utils.getApp()).areNotificationsEnabled()) {
512	                if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) {
513	                    return new SystemToast(toastUtils);
514	                }
515	                if (!UtilsBridge.isGrantedDrawOverlays()) {
516	                    return new SystemToast(toastUtils);
517	                }
518	            }
519	        }
520	
521	        // not use system or notification disable
522	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.N_MR1) {
523	            return new WindowManagerToast(toastUtils, WindowManager.LayoutParams.TYPE_TOAST);
524	        } else if (UtilsBridge.isGrantedDrawOverlays()) {
525	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
526	                return new WindowManagerToast(toastUtils, WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);
527	            } else {
528	                return new WindowManagerToast(toastUtils, WindowManager.LayoutParams.TYPE_PHONE);
529	            }
530	        }
531	        return new ActivityToast(toastUtils);
532	    }
