180	    private static void applyPressedBgStyle(View view, int style, float value) {
181	        if (view == null) return;
182	        Drawable background = view.getBackground();
183	        Object tag = view.getTag(-style);
184	        if (tag instanceof Drawable) {
185	            ViewCompat.setBackground(view, (Drawable) tag);
186	        } else {
187	            background = createStyleDrawable(background, style, value);
188	            ViewCompat.setBackground(view, background);
189	            view.setTag(-style, background);
190	        }
191	    }
