193	    private static Drawable createStyleDrawable(Drawable src, int style, float value) {
194	        if (src == null) {
195	            src = new ColorDrawable(0);
196	        }
197	        if (src.getConstantState() == null) return src;
198	
199	        Drawable pressed = src.getConstantState().newDrawable().mutate();
200	        if (style == PRESSED_BG_ALPHA_STYLE) {
201	            pressed = createAlphaDrawable(pressed, value);
202	        } else if (style == PRESSED_BG_DARK_STYLE) {
203	            pressed = createDarkDrawable(pressed, value);
204	        }
205	
206	        Drawable disable = src.getConstantState().newDrawable().mutate();
207	        disable = createAlphaDrawable(disable, 0.5f);
208	
209	        StateListDrawable drawable = new StateListDrawable();
210	        drawable.addState(new int[]{android.R.attr.state_pressed}, pressed);
211	        drawable.addState(new int[]{-android.R.attr.state_enabled}, disable);
212	        drawable.addState(StateSet.WILD_CARD, src);
213	        return drawable;
214	    }
