354	    public static void expandClickArea(@NonNull final View view,
355	                                       final int expandSizeTop,
356	                                       final int expandSizeLeft,
357	                                       final int expandSizeRight,
358	                                       final int expandSizeBottom) {
359	        final View parentView = (View) view.getParent();
360	        if (parentView == null) {
361	            Log.e("ClickUtils", "expandClickArea must have parent view.");
362	            return;
363	        }
364	        parentView.post(new Runnable() {
365	            @Override
366	            public void run() {
367	                final Rect rect = new Rect();
368	                view.getHitRect(rect);
369	                rect.top -= expandSizeTop;
370	                rect.bottom += expandSizeBottom;
371	                rect.left -= expandSizeLeft;
372	                rect.right += expandSizeRight;
373	                parentView.setTouchDelegate(new TouchDelegate(rect, view));
374	            }
375	        });
376	    }
