422	    public static abstract class OnDebouncingClickListener implements View.OnClickListener {
423	
424	        private static boolean mEnabled = true;
425	
426	        private static final Runnable ENABLE_AGAIN = new Runnable() {
427	            @Override
428	            public void run() {
429	                mEnabled = true;
430	            }
431	        };
432	
433	        private static boolean isValid(@NonNull final View view, final long duration) {
434	            return UtilsBridge.isValid(view, duration);
435	        }
436	
437	        private long    mDuration;
438	        private boolean mIsGlobal;
439	
440	        public OnDebouncingClickListener() {
441	            this(true, DEBOUNCING_DEFAULT_VALUE);
442	        }
443	
444	        public OnDebouncingClickListener(final boolean isGlobal) {
445	            this(isGlobal, DEBOUNCING_DEFAULT_VALUE);
446	        }
447	
448	        public OnDebouncingClickListener(final long duration) {
449	            this(true, duration);

450	        }
451	
452	        public OnDebouncingClickListener(final boolean isGlobal, final long duration) {
453	            mIsGlobal = isGlobal;
454	            mDuration = duration;
455	        }
456	
457	        public abstract void onDebouncingClick(View v);
458	
459	        @Override
460	        public final void onClick(View v) {
461	            if (mIsGlobal) {
462	                if (mEnabled) {
463	                    mEnabled = false;
464	                    v.postDelayed(ENABLE_AGAIN, mDuration);
465	                    onDebouncingClick(v);
466	                }
467	            } else {
468	                if (isValid(v, mDuration)) {
469	                    onDebouncingClick(v);
470	                }
471	            }
472	        }
473	    }
