475	    public static abstract class OnMultiClickListener implements View.OnClickListener {
476	
477	        private static final long INTERVAL_DEFAULT_VALUE = 666;
478	
479	        private final int  mTriggerClickCount;
480	        private final long mClickInterval;
481	
482	        private long mLastClickTime;
483	        private int  mClickCount;
484	
485	        public OnMultiClickListener(int triggerClickCount) {
486	            this(triggerClickCount, INTERVAL_DEFAULT_VALUE);
487	        }
488	
489	        public OnMultiClickListener(int triggerClickCount, long clickInterval) {
490	            this.mTriggerClickCount = triggerClickCount;
491	            this.mClickInterval = clickInterval;
492	        }
493	
494	        public abstract void onTriggerClick(View v);
495	
496	        public abstract void onBeforeTriggerClick(View v, int count);
497	
498	        @Override
499	        public void onClick(View v) {
500	            if (mTriggerClickCount <= 1) {
501	                onTriggerClick(v);
502	                return;
503	            }
504	            long curTime = System.currentTimeMillis();
505	
506	            if (curTime - mLastClickTime < mClickInterval) {
507	                mClickCount++;
508	                if (mClickCount == mTriggerClickCount) {
509	                    onTriggerClick(v);
510	                } else if (mClickCount < mTriggerClickCount) {
511	                    onBeforeTriggerClick(v, mClickCount);
512	                } else {
513	                    mClickCount = 1;
514	                    onBeforeTriggerClick(v, mClickCount);
515	                }
516	            } else {
517	                mClickCount = 1;
518	                onBeforeTriggerClick(v, mClickCount);
519	            }
520	            mLastClickTime = curTime;
521	        }
522	    }
