534	            int action = event.getAction();
535	            if (action == MotionEvent.ACTION_DOWN) {
536	                processScale(v, true);
537	                processAlpha(v, true);
538	            } else if (action == MotionEvent.ACTION_UP
539	                    || action == MotionEvent.ACTION_CANCEL) {
540	                processScale(v, false);
541	                processAlpha(v, false);
542	            }
543	            return false;
544	        }
