546	        private void processScale(final View view, boolean isDown) {
547	            Object tag = view.getTag(PRESSED_VIEW_SCALE_TAG);
548	            if (!(tag instanceof Float)) return;
549	            float value = isDown ? 1 + (Float) tag : 1;
550	            view.animate()
551	                    .scaleX(value)
552	                    .scaleY(value)
553	                    .setDuration(200)
554	                    .start();
555	        }
556	
557	        private void processAlpha(final View view, boolean isDown) {
558	            Object tag = view.getTag(isDown ? PRESSED_VIEW_ALPHA_TAG : PRESSED_VIEW_ALPHA_SRC_TAG);
559	            if (!(tag instanceof Float)) return;
560	            view.setAlpha((Float) tag);
561	        }
