212	    public static void log(final int type, final String tag, final Object... contents) {
213	        if (!CONFIG.isLogSwitch()) return;
214	        final int type_low = type & 0x0f, type_high = type & 0xf0;
215	        if (CONFIG.isLog2ConsoleSwitch() || CONFIG.isLog2FileSwitch() || type_high == FILE) {
216	            if (type_low < CONFIG.mConsoleFilter && type_low < CONFIG.mFileFilter) return;
217	            final TagHead tagHead = processTagAndHead(tag);
218	            final String body = processBody(type_high, contents);
219	            if (CONFIG.isLog2ConsoleSwitch() && type_high != FILE && type_low >= CONFIG.mConsoleFilter) {
220	                print2Console(type_low, tagHead.tag, tagHead.consoleHead, body);
221	            }
222	            if ((CONFIG.isLog2FileSwitch() || type_high == FILE) && type_low >= CONFIG.mFileFilter) {
223	                EXECUTOR.execute(new Runnable() {
224	                    @Override
225	                    public void run() {
226	                        print2File(type_low, tagHead.tag, tagHead.fileHead + body);
227	                    }
228	                });
229	            }
230	        }
231	    }
