252	    private static TagHead processTagAndHead(String tag) {
253	        if (!CONFIG.mTagIsSpace && !CONFIG.isLogHeadSwitch()) {
254	            tag = CONFIG.getGlobalTag();
255	        } else {
256	            final StackTraceElement[] stackTrace = new Throwable().getStackTrace();
257	            final int stackIndex = 3 + CONFIG.getStackOffset();
258	            if (stackIndex >= stackTrace.length) {
259	                StackTraceElement targetElement = stackTrace[3];
260	                final String fileName = getFileName(targetElement);
261	                if (CONFIG.mTagIsSpace && UtilsBridge.isSpace(tag)) {
262	                    int index = fileName.indexOf('.');// Use proguard may not find '.'.
263	                    tag = index == -1 ? fileName : fileName.substring(0, index);
264	                }
265	                return new TagHead(tag, null, ": ");
266	            }
267	            StackTraceElement targetElement = stackTrace[stackIndex];
268	            final String fileName = getFileName(targetElement);
269	            if (CONFIG.mTagIsSpace && UtilsBridge.isSpace(tag)) {
270	                int index = fileName.indexOf('.');// Use proguard may not find '.'.
271	                tag = index == -1 ? fileName : fileName.substring(0, index);
272	            }
273	            if (CONFIG.isLogHeadSwitch()) {
274	                String tName = Thread.currentThread().getName();
275	                final String head = new Formatter()
276	                        .format("%s, %s.%s(%s:%d)",
277	                                tName,
278	                                targetElement.getClassName(),
279	                                targetElement.getMethodName(),
280	                                fileName,
281	                                targetElement.getLineNumber())
282	                        .toString();
283	                final String fileHead = " [" + head + "]: ";
284	                if (CONFIG.getStackDeep() <= 1) {
285	                    return new TagHead(tag, new String[]{head}, fileHead);
286	                } else {
287	                    final String[] consoleHead =
288	                            new String[Math.min(
289	                                    CONFIG.getStackDeep(),
290	                                    stackTrace.length - stackIndex
291	                            )];
292	                    consoleHead[0] = head;
293	                    int spaceLen = tName.length() + 2;
294	                    String space = new Formatter().format("%" + spaceLen + "s", "").toString();
295	                    for (int i = 1, len = consoleHead.length; i < len; ++i) {
296	                        targetElement = stackTrace[i + stackIndex];
297	                        consoleHead[i] = new Formatter()
298	                                .format("%s%s.%s(%s:%d)",
299	                                        space,
300	                                        targetElement.getClassName(),
301	                                        targetElement.getMethodName(),
302	                                        getFileName(targetElement),
303	                                        targetElement.getLineNumber())
304	                                .toString();
305	                    }
306	                    return new TagHead(tag, consoleHead, fileHead);
307	                }
308	            }
309	        }
310	        return new TagHead(tag, null, ": ");
311	    }
