313	    private static String getFileName(final StackTraceElement targetElement) {
314	        String fileName = targetElement.getFileName();
315	        if (fileName != null) return fileName;
316	        // If name of file is null, should add
317	        // "-keepattributes SourceFile,LineNumberTable" in proguard file.
318	        String className = targetElement.getClassName();
319	        String[] classNameInfo = className.split("\\.");
320	        if (classNameInfo.length > 0) {
321	            className = classNameInfo[classNameInfo.length - 1];
322	        }
323	        int index = className.indexOf('$');
324	        if (index != -1) {
325	            className = className.substring(0, index);
326	        }
327	        return className + ".java";
328	    }
