430	    private static String processSingleTagMsg(final int type,
431	                                              final String tag,
432	                                              final String[] head,
433	                                              final String msg) {
434	        StringBuilder sb = new StringBuilder();
435	        if (CONFIG.isLogBorderSwitch()) {
436	            sb.append(PLACEHOLDER).append(LINE_SEP);
437	            sb.append(TOP_BORDER).append(LINE_SEP);
438	            if (head != null) {
439	                for (String aHead : head) {
440	                    sb.append(LEFT_BORDER).append(aHead).append(LINE_SEP);
441	                }
442	                sb.append(MIDDLE_BORDER).append(LINE_SEP);
443	            }
444	            for (String line : msg.split(LINE_SEP)) {
445	                sb.append(LEFT_BORDER).append(line).append(LINE_SEP);
446	            }
447	            sb.append(BOTTOM_BORDER);
448	        } else {
449	            if (head != null) {
450	                sb.append(PLACEHOLDER).append(LINE_SEP);
451	                for (String aHead : head) {
452	                    sb.append(aHead).append(LINE_SEP);
453	                }
454	            }
455	            sb.append(msg);
456	        }
457	        return sb.toString();
458	    }
