460	    private static void printSingleTagMsg(final int type, final String tag, final String msg) {
461	        int len = msg.length();
462	        int countOfSub = CONFIG.isLogBorderSwitch() ? (len - BOTTOM_BORDER.length()) / MAX_LEN : len / MAX_LEN;
463	        if (countOfSub > 0) {
464	            if (CONFIG.isLogBorderSwitch()) {
465	                print2Console(type, tag, msg.substring(0, MAX_LEN) + LINE_SEP + BOTTOM_BORDER);
466	                int index = MAX_LEN;
467	                for (int i = 1; i < countOfSub; i++) {
468	                    print2Console(type, tag, PLACEHOLDER + LINE_SEP + TOP_BORDER + LINE_SEP
469	                            + LEFT_BORDER + msg.substring(index, index + MAX_LEN)
470	                            + LINE_SEP + BOTTOM_BORDER);
471	                    index += MAX_LEN;
472	                }
473	                if (index != len - BOTTOM_BORDER.length()) {
474	                    print2Console(type, tag, PLACEHOLDER + LINE_SEP + TOP_BORDER + LINE_SEP
475	                            + LEFT_BORDER + msg.substring(index, len));
476	                }
477	            } else {
478	                print2Console(type, tag, msg.substring(0, MAX_LEN));
479	                int index = MAX_LEN;
480	                for (int i = 1; i < countOfSub; i++) {
481	                    print2Console(type, tag,
482	                            PLACEHOLDER + LINE_SEP + msg.substring(index, index + MAX_LEN));
483	                    index += MAX_LEN;
484	                }
485	                if (index != len) {
486	                    print2Console(type, tag, PLACEHOLDER + LINE_SEP + msg.substring(index, len));
487	                }
488	            }
489	        } else {
490	            print2Console(type, tag, msg);
491	        }
492	    }
