539	        if (!UtilsBridge.createOrExistsDir(file.getParentFile())) return false;
540	        try {
541	            deleteDueLogs(filePath, date);
542	            boolean isCreate = file.createNewFile();
543	            if (isCreate) {
544	                printDeviceInfo(filePath, date);
