553	    private static void deleteDueLogs(final String filePath, final String date) {
554	        if (CONFIG.getSaveDays() <= 0) return;
555	        File file = new File(filePath);
556	        File parentFile = file.getParentFile();
557	        File[] files = parentFile.listFiles(new FilenameFilter() {
558	            @Override
559	            public boolean accept(File dir, String name) {
560	                return isMatchLogFileName(name);
561	            }
562	        });
563	        if (files == null || files.length <= 0) return;
564	        final SimpleDateFormat sdf = new SimpleDateFormat("yyyy_MM_dd", Locale.getDefault());
565	        try {
566	            long dueMillis = sdf.parse(date).getTime() - CONFIG.getSaveDays() * 86400000L;
567	            for (final File aFile : files) {
568	                String name = aFile.getName();
569	                int l = name.length();
570	                String logDay = findDate(name);
571	                if (sdf.parse(logDay).getTime() <= dueMillis) {
572	                    EXECUTOR.execute(new Runnable() {
573	                        @Override
574	                        public void run() {
575	                            boolean delete = aFile.delete();
576	                            if (!delete) {
577	                                Log.e("LogUtils", "delete " + aFile + " failed!");
578	                            }
579	                        }
580	                    });
581	                }
582	            }
583	        } catch (ParseException e) {
584	            e.printStackTrace();
585	        }
586	    }
