592	    private static String findDate(String str) {
593	        Pattern pattern = Pattern.compile("[0-9]{4}_[0-9]{2}_[0-9]{2}");
594	        Matcher matcher = pattern.matcher(str);
595	        if (matcher.find()) {
596	            return matcher.group();
597	        }
598	        return "";
599	    }
