917	        static String object2String(Object object) {
918	            return object2String(object, -1);
919	        }
920	
921	        static String object2String(Object object, int type) {
922	            if (object.getClass().isArray()) return array2String(object);
923	            if (object instanceof Throwable)
924	                return UtilsBridge.getFullStackTrace((Throwable) object);
925	            if (object instanceof Bundle) return bundle2String((Bundle) object);
926	            if (object instanceof Intent) return intent2String((Intent) object);
927	            if (type == JSON) {
928	                return object2Json(object);
929	            } else if (type == XML) {
930	                return formatXml(object.toString());
931	            }
932	            return object.toString();
