935	        private static String bundle2String(Bundle bundle) {
936	            Iterator<String> iterator = bundle.keySet().iterator();
937	            if (!iterator.hasNext()) {
938	                return "Bundle {}";
939	            }
940	            StringBuilder sb = new StringBuilder(128);
941	            sb.append("Bundle { ");
942	            for (; ; ) {
943	                String key = iterator.next();
944	                Object value = bundle.get(key);
945	                sb.append(key).append('=');
946	                if (value instanceof Bundle) {
947	                    sb.append(value == bundle ? "(this Bundle)" : bundle2String((Bundle) value));
948	                } else {
949	                    sb.append(formatObject(value));
950	                }
951	                if (!iterator.hasNext()) return sb.append(" }").toString();
952	                sb.append(',').append(' ');
953	            }
954	        }
955	
956	        private static String intent2String(Intent intent) {
957	            StringBuilder sb = new StringBuilder(128);
958	            sb.append("Intent { ");
959	            boolean first = true;
960	            String mAction = intent.getAction();
961	            if (mAction != null) {
962	                sb.append("act=").append(mAction);
963	                first = false;
964	            }
965	            Set<String> mCategories = intent.getCategories();
966	            if (mCategories != null) {
967	                if (!first) {
968	                    sb.append(' ');
969	                }
970	                first = false;
971	                sb.append("cat=[");
972	                boolean firstCategory = true;
973	                for (String c : mCategories) {
974	                    if (!firstCategory) {
975	                        sb.append(',');
976	                    }
977	                    sb.append(c);
978	                    firstCategory = false;
979	                }
980	                sb.append("]");
981	            }
982	            Uri mData = intent.getData();
983	            if (mData != null) {
984	                if (!first) {
985	                    sb.append(' ');
986	                }
987	                first = false;
988	                sb.append("dat=").append(mData);
989	            }
990	            String mType = intent.getType();
991	            if (mType != null) {
992	                if (!first) {
993	                    sb.append(' ');
994	                }
995	                first = false;
996	                sb.append("typ=").append(mType);
997	            }
998	            int mFlags = intent.getFlags();
999	            if (mFlags != 0) {
1000	                if (!first) {
1001	                    sb.append(' ');
1002	                }
1003	                first = false;
1004	                sb.append("flg=0x").append(Integer.toHexString(mFlags));
1005	            }
1006	            String mPackage = intent.getPackage();
1007	            if (mPackage != null) {
1008	                if (!first) {
1009	                    sb.append(' ');
1010	                }
1011	                first = false;
1012	                sb.append("pkg=").append(mPackage);
1013	            }
1014	            ComponentName mComponent = intent.getComponent();
1015	            if (mComponent != null) {
1016	                if (!first) {
1017	                    sb.append(' ');
1018	                }
1019	                first = false;
1020	                sb.append("cmp=").append(mComponent.flattenToShortString());
1021	            }
1022	            Rect mSourceBounds = intent.getSourceBounds();
1023	            if (mSourceBounds != null) {
1024	                if (!first) {
1025	                    sb.append(' ');
1026	                }
1027	                first = false;
1028	                sb.append("bnds=").append(mSourceBounds.toShortString());
1029	            }
1030	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
1031	                ClipData mClipData = intent.getClipData();
1032	                if (mClipData != null) {
1033	                    if (!first) {
1034	                        sb.append(' ');
1035	                    }
1036	                    first = false;
1037	                    clipData2String(mClipData, sb);
1038	                }
1039	            }
1040	            Bundle mExtras = intent.getExtras();
1041	            if (mExtras != null) {
1042	                if (!first) {
1043	                    sb.append(' ');
1044	                }
1045	                first = false;
1046	                sb.append("extras={");
1047	                sb.append(bundle2String(mExtras));
1048	                sb.append('}');
1049	            }
1050	            if (Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.ICE_CREAM_SANDWICH_MR1) {
1051	                Intent mSelector = intent.getSelector();
1052	                if (mSelector != null) {
1053	                    if (!first) {
1054	                        sb.append(' ');
1055	                    }
1056	                    first = false;
1057	                    sb.append("sel={");
1058	                    sb.append(mSelector == intent ? "(this Intent)" : intent2String(mSelector));
1059	                    sb.append("}");
1060	                }
1061	            }
1062	            sb.append(" }");
1063	            return sb.toString();
1064	        }
1065	
1066	        @RequiresApi(api = Build.VERSION_CODES.JELLY_BEAN)
1067	        private static void clipData2String(ClipData clipData, StringBuilder sb) {
1068	            ClipData.Item item = clipData.getItemAt(0);
1069	            if (item == null) {
1070	                sb.append("ClipData.Item {}");
1071	                return;
1072	            }
1073	            sb.append("ClipData.Item { ");
1074	            String mHtmlText = item.getHtmlText();
1075	            if (mHtmlText != null) {
1076	                sb.append("H:");
1077	                sb.append(mHtmlText);
1078	                sb.append("}");
1079	                return;
1080	            }
1081	            CharSequence mText = item.getText();
1082	            if (mText != null) {
1083	                sb.append("T:");
1084	                sb.append(mText);
1085	                sb.append("}");
1086	                return;
1087	            }
1088	            Uri uri = item.getUri();
1089	            if (uri != null) {
1090	                sb.append("U:").append(uri);
1091	                sb.append("}");
1092	                return;
1093	            }
1094	            Intent intent = item.getIntent();
1095	            if (intent != null) {
1096	                sb.append("I:");
1097	                sb.append(intent2String(intent));
1098	                sb.append("}");
1099	                return;
1100	            }
1101	            sb.append("NULL");
1102	            sb.append("}");
1103	        }
