1105	        private static String object2Json(Object object) {
1106	            if (object instanceof CharSequence) {
1107	                return UtilsBridge.formatJson(object.toString());
1108	            }
1109	            try {
1110	                return UtilsBridge.getGson4LogUtils().toJson(object);
1111	            } catch (Throwable t) {
1112	                return object.toString();
1113	            }
1114	        }
