1116	        private static String formatJson(String json) {
1117	            try {
1118	                for (int i = 0, len = json.length(); i < len; i++) {
1119	                    char c = json.charAt(i);
1120	                    if (c == '{') {
1121	                        return new JSONObject(json).toString(2);
1122	                    } else if (c == '[') {
1123	                        return new JSONArray(json).toString(2);
1124	                    } else if (!Character.isWhitespace(c)) {
1125	                        return json;
1126	                    }
1127	                }
1128	            } catch (JSONException e) {
1129	                e.printStackTrace();
1130	            }
1131	            return json;
1132	        }
