1173	    private static <T> Class getTypeClassFromParadigm(final IFormatter<T> formatter) {
1174	        Type[] genericInterfaces = formatter.getClass().getGenericInterfaces();
1175	        Type type;
1176	        if (genericInterfaces.length == 1) {
1177	            type = genericInterfaces[0];
1178	        } else {
1179	            type = formatter.getClass().getGenericSuperclass();
1180	        }
1181	        type = ((ParameterizedType) type).getActualTypeArguments()[0];
1182	        while (type instanceof ParameterizedType) {
1183	            type = ((ParameterizedType) type).getRawType();
1184	        }
1185	        String className = type.toString();
1186	        if (className.startsWith("class ")) {
1187	            className = className.substring(6);
1188	        } else if (className.startsWith("interface ")) {
1189	            className = className.substring(10);
1190	        }
1191	        try {
1192	            return Class.forName(className);
1193	        } catch (ClassNotFoundException e) {
1194	            e.printStackTrace();
1195	        }
1196	        return null;
1197	    }
