1199	    private static Class getClassFromObject(final Object obj) {
1200	        Class objClass = obj.getClass();
1201	        if (objClass.isAnonymousClass() || objClass.isSynthetic()) {
1202	            Type[] genericInterfaces = objClass.getGenericInterfaces();
1203	            String className;
1204	            if (genericInterfaces.length == 1) {// interface
1205	                Type type = genericInterfaces[0];
1206	                while (type instanceof ParameterizedType) {
1207	                    type = ((ParameterizedType) type).getRawType();
1208	                }
1209	                className = type.toString();
1210	            } else {// abstract class or lambda
1211	                Type type = objClass.getGenericSuperclass();
1212	                while (type instanceof ParameterizedType) {
1213	                    type = ((ParameterizedType) type).getRawType();
1214	                }
1215	                className = type.toString();
1216	            }
1217	
1218	            if (className.startsWith("class ")) {
1219	                className = className.substring(6);
1220	            } else if (className.startsWith("interface ")) {
1221	                className = className.substring(10);
1222	            }
1223	            try {
1224	                return Class.forName(className);
1225	            } catch (ClassNotFoundException e) {
1226	                e.printStackTrace();
1227	            }
1228	        }
1229	        return objClass;
