268	    /**
269	     * Execute the command.
270	     *
271	     * @param commands        The commands.
272	     * @param envp            Array of strings, each element of which
273	     *                        has environment variable settings in the format
274	     *                        <i>name</i>=<i>value</i>, or
275	     *                        <tt>null</tt> if the subprocess should inherit
276	     *                        the environment of the current process.
277	     * @param isRooted        True to use root, false otherwise.
278	     * @param isNeedResultMsg True to return the message of result, false otherwise.
279	     * @return the single {@link CommandResult} instance
280	     */
281	    public static CommandResult execCmd(final String[] commands,
282	                                        final String[] envp,
283	                                        final boolean isRooted,
284	                                        final boolean isNeedResultMsg) {
285	        int result = -1;
286	        if (commands == null || commands.length == 0) {
287	            return new CommandResult(result, "", "");
288	        }
289	        Process process = null;
290	        BufferedReader successResult = null;
291	        BufferedReader errorResult = null;
292	        StringBuilder successMsg = null;
293	        StringBuilder errorMsg = null;
294	        DataOutputStream os = null;
295	        try {
296	            process = Runtime.getRuntime().exec(isRooted ? "su" : "sh", envp, null);
297	            os = new DataOutputStream(process.getOutputStream());
298	            for (String command : commands) {
299	                if (command == null) continue;
300	                os.write(command.getBytes());
301	                os.writeBytes(LINE_SEP);
302	                os.flush();
303	            }
304	            os.writeBytes("exit" + LINE_SEP);
305	            os.flush();
306	            result = process.waitFor();
307	            if (isNeedResultMsg) {
308	                successMsg = new StringBuilder();
309	                errorMsg = new StringBuilder();
310	                successResult = new BufferedReader(
311	                        new InputStreamReader(process.getInputStream(), "UTF-8")
312	                );
313	                errorResult = new BufferedReader(
314	                        new InputStreamReader(process.getErrorStream(), "UTF-8")
315	                );
316	                String line;
317	                if ((line = successResult.readLine()) != null) {
318	                    successMsg.append(line);
319	                    while ((line = successResult.readLine()) != null) {
320	                        successMsg.append(LINE_SEP).append(line);
321	                    }
322	                }
323	                if ((line = errorResult.readLine()) != null) {
324	                    errorMsg.append(line);
325	                    while ((line = errorResult.readLine()) != null) {
326	                        errorMsg.append(LINE_SEP).append(line);
327	                    }
328	                }
329	            }
330	        } catch (Exception e) {
331	            e.printStackTrace();
332	        } finally {
333	            try {
334	                if (os != null) {
335	                    os.close();
336	                }
337	            } catch (IOException e) {
338	                e.printStackTrace();
339	            }
340	            try {
341	                if (successResult != null) {
342	                    successResult.close();
343	                }
344	            } catch (IOException e) {
345	                e.printStackTrace();
346	            }
347	            try {
348	                if (errorResult != null) {
349	                    errorResult.close();
350	                }
351	            } catch (IOException e) {
352	                e.printStackTrace();
353	            }
354	            if (process != null) {
355	                process.destroy();
356	            }
357	        }
358	        return new CommandResult(
359	                result,
360	                successMsg == null ? "" : successMsg.toString(),
361	                errorMsg == null ? "" : errorMsg.toString()
362	        );
363	    }
364	
365	    /**
366	     * The result of command.
367	     */
368	    public static class CommandResult {
369	        public int    result;
370	        public String successMsg;
371	        public String errorMsg;
372	
373	        public CommandResult(final int result, final String successMsg, final String errorMsg) {
374	            this.result = result;
375	            this.successMsg = successMsg;
376	            this.errorMsg = errorMsg;
377	        }
378	
379	        @Override
380	        public String toString() {
381	            return "result: " + result + "\n" +
382	                    "successMsg: " + successMsg + "\n" +
383	                    "errorMsg: " + errorMsg;
384	        }
385	    }
