191	    private static boolean zipFile(final File srcFile,
192	                                   String rootPath,
193	                                   final ZipOutputStream zos,
194	                                   final String comment)
195	            throws IOException {
196	        rootPath = rootPath + (UtilsBridge.isSpace(rootPath) ? "" : File.separator) + srcFile.getName();
197	        if (srcFile.isDirectory()) {
198	            File[] fileList = srcFile.listFiles();
199	            if (fileList == null || fileList.length <= 0) {
200	                ZipEntry entry = new ZipEntry(rootPath + '/');
201	                entry.setComment(comment);
202	                zos.putNextEntry(entry);
203	                zos.closeEntry();
204	            } else {
205	                for (File file : fileList) {
206	                    if (!zipFile(file, rootPath, zos, comment)) return false;
207	                }
208	            }
209	        } else {
210	            InputStream is = null;
211	            try {
212	                is = new BufferedInputStream(new FileInputStream(srcFile));
213	                ZipEntry entry = new ZipEntry(rootPath);
214	                entry.setComment(comment);
215	                zos.putNextEntry(entry);
216	                byte buffer[] = new byte[BUFFER_LEN];
217	                int len;
218	                while ((len = is.read(buffer, 0, BUFFER_LEN)) != -1) {
219	                    zos.write(buffer, 0, len);
220	                }
221	                zos.closeEntry();
222	            } finally {
223	                if (is != null) {
224	                    is.close();
225	                }
226	            }
227	        }
228	        return true;
