296	                    String entryName = entry.getName().replace("\\", "/");
297	                    if (entryName.contains("../")) {
298	                        Log.e("ZipUtils", "entryName: " + entryName + " is dangerous!");
299	                        continue;
300	                    }
301	                    if (!unzipChildFile(destDir, files, zip, entry, entryName)) return files;
302	                }
303	            } else {
304	                while (entries.hasMoreElements()) {
