87	    /**
88	     * Return whether <em>you</em> have been granted the permissions.
89	     *
90	     * @param permissions The permissions.
91	     * @return {@code true}: yes<br>{@code false}: no
92	     */
93	    public static boolean isGranted(final String... permissions) {
94	        Pair<List<String>, List<String>> requestAndDeniedPermissions = getRequestAndDeniedPermissions(permissions);
95	        List<String> deniedPermissions = requestAndDeniedPermissions.second;
96	        if (!deniedPermissions.isEmpty()) {
97	            return false;
98	        }
99	        List<String> requestPermissions = requestAndDeniedPermissions.first;
100	        for (String permission : requestPermissions) {
101	            if (!isGranted(permission)) {
102	                return false;
103	            }
104	        }
105	        return true;
106	    }
107	
108	    private static Pair<List<String>, List<String>> getRequestAndDeniedPermissions(final String... permissionsParam) {
109	        List<String> requestPermissions = new ArrayList<>();
110	        List<String> deniedPermissions = new ArrayList<>();
111	        List<String> appPermissions = getPermissions();
112	        for (String param : permissionsParam) {
113	            boolean isIncludeInManifest = false;
114	            String[] permissions = PermissionConstants.getPermissions(param);
115	            for (String permission : permissions) {
116	                if (appPermissions.contains(permission)) {
117	                    requestPermissions.add(permission);
118	                    isIncludeInManifest = true;
119	                }
120	            }
121	            if (!isIncludeInManifest) {
122	                deniedPermissions.add(param);
123	                Log.e("PermissionUtils", "U should add the permission of " + param + " in manifest.");
124	            }
125	        }
126	        return Pair.create(requestPermissions, deniedPermissions);
127	    }
