297	    /**
298	     * Start request.
299	     */
300	    public void request() {
301	        if (mPermissionsParam == null || mPermissionsParam.length <= 0) {
302	            Log.w("PermissionUtils", "No permissions to request.");
303	            return;
304	        }
305	
306	        mPermissions = new LinkedHashSet<>();
307	        mPermissionsRequest = new ArrayList<>();
308	        mPermissionsGranted = new ArrayList<>();
309	        mPermissionsDenied = new ArrayList<>();
310	        mPermissionsDeniedForever = new ArrayList<>();
311	
312	        Pair<List<String>, List<String>> requestAndDeniedPermissions = getRequestAndDeniedPermissions(mPermissionsParam);
313	        mPermissions.addAll(requestAndDeniedPermissions.first);
314	        mPermissionsDenied.addAll(requestAndDeniedPermissions.second);
315	
316	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) {
317	            mPermissionsGranted.addAll(mPermissions);
318	            requestCallback();
319	        } else {
320	            for (String permission : mPermissions) {
321	                if (isGranted(permission)) {
322	                    mPermissionsGranted.add(permission);
323	                } else {
324	                    mPermissionsRequest.add(permission);
325	                }
326	            }
327	            if (mPermissionsRequest.isEmpty()) {
328	                requestCallback();
329	            } else {
330	                startPermissionActivity();
331	            }
332	        }
333	    }
