340	    @RequiresApi(api = Build.VERSION_CODES.M)
341	    private boolean shouldRationale(final UtilsTransActivity activity,
342	                                    final Runnable againRunnable) {
343	        boolean isRationale = false;
344	        if (mOnRationaleListener != null) {
345	            for (String permission : mPermissionsRequest) {
346	                if (activity.shouldShowRequestPermissionRationale(permission)) {
347	                    rationalInner(activity, againRunnable);
348	                    isRationale = true;
349	                    break;
350	                }
351	            }
352	            mOnRationaleListener = null;
353	        }
354	        return isRationale;
355	    }
356	
357	    private void rationalInner(final UtilsTransActivity activity, final Runnable againRunnable) {
358	        getPermissionsStatus(activity);
359	        mOnRationaleListener.rationale(activity, new OnRationaleListener.ShouldRequest() {
360	            @Override
361	            public void again(boolean again) {
362	                if (again) {
363	                    mPermissionsDenied = new ArrayList<>();
364	                    mPermissionsDeniedForever = new ArrayList<>();
365	                    againRunnable.run();
366	                } else {
367	                    activity.finish();
368	                    requestCallback();
369	                }
370	            }
371	        });
372	    }
373	
374	    private void getPermissionsStatus(final Activity activity) {
375	        for (String permission : mPermissionsRequest) {
376	            if (isGranted(permission)) {
377	                mPermissionsGranted.add(permission);
378	            } else {
379	                mPermissionsDenied.add(permission);
380	                if (!activity.shouldShowRequestPermissionRationale(permission)) {
381	                    mPermissionsDeniedForever.add(permission);
382	                }
383	            }
384	        }
385	    }
386	
387	    private void requestCallback() {
388	        if (mSingleCallback != null) {
389	            mSingleCallback.callback(mPermissionsDenied.isEmpty(),
390	                    mPermissionsGranted, mPermissionsDeniedForever, mPermissionsDenied);
391	            mSingleCallback = null;
392	        }
393	        if (mSimpleCallback != null) {
394	            if (mPermissionsDenied.isEmpty()) {
395	                mSimpleCallback.onGranted();
396	            } else {
397	                mSimpleCallback.onDenied();
398	            }
399	            mSimpleCallback = null;
400	        }
401	        if (mFullCallback != null) {
402	            if (mPermissionsRequest.size() == 0
403	                    || mPermissionsGranted.size() > 0) {
404	                mFullCallback.onGranted(mPermissionsGranted);
405	            }
406	            if (!mPermissionsDenied.isEmpty()) {
407	                mFullCallback.onDenied(mPermissionsDeniedForever, mPermissionsDenied);
408	            }
409	            mFullCallback = null;
410	        }
411	        mOnRationaleListener = null;
412	        mThemeCallback = null;
413	    }
