441	        @Override
442	        public void onCreated(@NonNull final UtilsTransActivity activity, @Nullable Bundle savedInstanceState) {
443	            activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE
444	                    | WindowManager.LayoutParams.FLAG_WATCH_OUTSIDE_TOUCH);
445	            int type = activity.getIntent().getIntExtra(TYPE, -1);
446	            if (type == TYPE_RUNTIME) {
447	                if (sInstance == null) {
448	                    Log.e("PermissionUtils", "sInstance is null.");
449	                    activity.finish();
450	                    return;
451	                }
452	                if (sInstance.mPermissionsRequest == null) {
453	                    Log.e("PermissionUtils", "mPermissionsRequest is null.");
454	                    activity.finish();
455	                    return;
456	                }
457	                if (sInstance.mPermissionsRequest.size() <= 0) {
458	                    Log.e("PermissionUtils", "mPermissionsRequest's size is no more than 0.");
459	                    activity.finish();
460	                    return;
461	                }
462	                if (sInstance.mThemeCallback != null) {
463	                    sInstance.mThemeCallback.onActivityCreate(activity);
464	                }
465	                if (sInstance.mOnExplainListener != null) {
466	                    sInstance.mOnExplainListener.explain(activity, sInstance.mPermissionsRequest, new OnExplainListener.ShouldRequest() {
467	                        @Override
468	                        public void start(boolean start) {
469	                            if (!start) {
470	                                activity.finish();
471	                            } else {
472	                                requestPermissions(activity);
473	                            }
474	                        }
475	                    });
476	                    sInstance.mOnExplainListener = null;
477	                    return;
478	                }
479	                requestPermissions(activity);
480	            } else if (type == TYPE_WRITE_SETTINGS) {
481	                currentRequestCode = TYPE_WRITE_SETTINGS;
482	                startWriteSettingsActivity(activity, TYPE_WRITE_SETTINGS);
483	            } else if (type == TYPE_DRAW_OVERLAYS) {
484	                currentRequestCode = TYPE_DRAW_OVERLAYS;
485	                startOverlayPermissionActivity(activity, TYPE_DRAW_OVERLAYS);
486	            } else {
487	                activity.finish();
488	                Log.e("PermissionUtils", "type is wrong.");
489	            }
490	        }
