64	        return (int) (pxValue / fontScale + 0.5f);
65	    }
66	
67	    /**
68	     * Converts an unpacked complex data value holding a dimension to its final floating
69	     * point value. The two parameters <var>unit</var> and <var>value</var>
70	     * are as in {@link TypedValue#TYPE_DIMENSION}.
71	     *
72	     * @param value The value to apply the unit to.
73	     * @param unit  The unit to convert from.
74	     * @return The complex floating point value multiplied by the appropriate
75	     * metrics depending on its unit.
76	     */
77	    public static float applyDimension(final float value, final int unit) {
78	        DisplayMetrics metrics = Resources.getSystem().getDisplayMetrics();
79	        switch (unit) {
80	            case TypedValue.COMPLEX_UNIT_PX:
81	                return value;
82	            case TypedValue.COMPLEX_UNIT_DIP:
83	                return value * metrics.density;
84	            case TypedValue.COMPLEX_UNIT_SP:
85	                return value * metrics.scaledDensity;
86	            case TypedValue.COMPLEX_UNIT_PT:
87	                return value * metrics.xdpi * (1.0f / 72);
88	            case TypedValue.COMPLEX_UNIT_IN:
89	                return value * metrics.xdpi;
90	            case TypedValue.COMPLEX_UNIT_MM:
91	                return value * metrics.xdpi * (1.0f / 25.4f);
92	        }
93	        return 0;
94	    }
