143	     * Measure the view.
144	     *
145	     * @param view The view.
146	     * @return arr[0]: view's width, arr[1]: view's height
147	     */
148	    public static int[] measureView(final View view) {
149	        ViewGroup.LayoutParams lp = view.getLayoutParams();
150	        if (lp == null) {
151	            lp = new ViewGroup.LayoutParams(
152	                    ViewGroup.LayoutParams.MATCH_PARENT,
153	                    ViewGroup.LayoutParams.WRAP_CONTENT
154	            );
155	        }
156	        int widthSpec = ViewGroup.getChildMeasureSpec(0, 0, lp.width);
157	        int lpHeight = lp.height;
158	        int heightSpec;
159	        if (lpHeight > 0) {
160	            heightSpec = View.MeasureSpec.makeMeasureSpec(lpHeight, View.MeasureSpec.EXACTLY);
161	        } else {
162	            heightSpec = View.MeasureSpec.makeMeasureSpec(0, View.MeasureSpec.UNSPECIFIED);
163	        }
164	        view.measure(widthSpec, heightSpec);
165	        return new int[]{view.getMeasuredWidth(), view.getMeasuredHeight()};
166	    }
