221	    /**
222	     * Register soft input changed listener.
223	     *
224	     * @param window The window.
225	     * @param listener The soft input changed listener.
226	     */
227	    public static void registerSoftInputChangedListener(@NonNull final Window window,
228	                                                        @NonNull
229	                                                        final OnSoftInputChangedListener listener) {
230	        final int flags = window.getAttributes().flags;
231	        if ((flags & WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS) != 0) {
232	            window.clearFlags(WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS);
233	        }
234	        final FrameLayout contentView = window.findViewById(android.R.id.content);
235	        final int[] decorViewInvisibleHeightPre = { getDecorViewInvisibleHeight(window) };
236	        OnGlobalLayoutListener onGlobalLayoutListener = new OnGlobalLayoutListener() {
237	            @Override
238	            public void onGlobalLayout() {
239	                int height = getDecorViewInvisibleHeight(window);
240	                if (decorViewInvisibleHeightPre[0] != height) {
241	                    listener.onSoftInputChanged(height);
242	                    decorViewInvisibleHeightPre[0] = height;
243	                }
244	            }
245	        };
246	        contentView.getViewTreeObserver().addOnGlobalLayoutListener(onGlobalLayoutListener);
247	        contentView.setTag(TAG_ON_GLOBAL_LAYOUT_LISTENER, onGlobalLayoutListener);
248	    }
