251	     * Unregister soft input changed listener.
252	     *
253	     * @param window The window.
254	     */
255	    public static void unregisterSoftInputChangedListener(@NonNull final Window window) {
256	        final View contentView = window.findViewById(android.R.id.content);
257	        if (contentView == null) {
258	            return;
259	        }
260	        Object tag = contentView.getTag(TAG_ON_GLOBAL_LAYOUT_LISTENER);
261	        if (tag instanceof OnGlobalLayoutListener) {
262	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
263	                contentView.getViewTreeObserver().removeOnGlobalLayoutListener((OnGlobalLayoutListener) tag);
264	                //这里会发生内存泄漏 如果不设置为null
265	                contentView.setTag(TAG_ON_GLOBAL_LAYOUT_LISTENER, null);
266	            }
267	        }
268	    }
