282	     * <p>It will clean the adjustResize</p>
283	     *
284	     * @param window The window.
285	     */
286	    public static void fixAndroidBug5497(@NonNull final Window window) {
287	        int softInputMode = window.getAttributes().softInputMode;
288	        window.setSoftInputMode(
289	            softInputMode & ~WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
290	        final FrameLayout contentView = window.findViewById(android.R.id.content);
291	        final View contentViewChild = contentView.getChildAt(0);
292	        final int paddingBottom = contentViewChild.getPaddingBottom();
293	        final int[] contentViewInvisibleHeightPre5497 = { getContentViewInvisibleHeight(window) };
294	        contentView.getViewTreeObserver().addOnGlobalLayoutListener(new OnGlobalLayoutListener() {
295	            @Override
296	            public void onGlobalLayout() {
297	                int height = getContentViewInvisibleHeight(window);
298	                if (contentViewInvisibleHeightPre5497[0] != height) {
299	                    contentViewChild.setPadding(contentViewChild.getPaddingLeft(),
300	                        contentViewChild.getPaddingTop(), contentViewChild.getPaddingRight(),
301	                        paddingBottom + getDecorViewInvisibleHeight(window));
302	                    contentViewInvisibleHeightPre5497[0] = height;
303	                }
304	            }
305	        });
306	    }
