308	    private static int getContentViewInvisibleHeight(final Window window) {
309	        final View contentView = window.findViewById(android.R.id.content);
310	        if (contentView == null) {
311	            return 0;
312	        }
313	        final Rect outRect = new Rect();
314	        contentView.getWindowVisibleDisplayFrame(outRect);
315	        Log.d("KeyboardUtils",
316	            "getContentViewInvisibleHeight: " + (contentView.getBottom() - outRect.bottom));
317	        int delta = Math.abs(contentView.getBottom() - outRect.bottom);
318	        if (delta <= UtilsBridge.getStatusBarHeight() + UtilsBridge.getNavBarHeight()) {
319	            return 0;
320	        }
321	        return delta;
322	    }
