338	    public static void fixSoftInputLeaks(@NonNull final Window window) {
339	        InputMethodManager imm =
340	            (InputMethodManager) Utils.getApp().getSystemService(Context.INPUT_METHOD_SERVICE);
341	        if (imm == null) {
342	            return;
343	        }
344	        String[] leakViews =
345	            new String[] { "mLastSrvView", "mCurRootView", "mServedView", "mNextServedView" };
346	        for (String leakView : leakViews) {
347	            try {
348	                Field leakViewField = InputMethodManager.class.getDeclaredField(leakView);
349	                if (!leakViewField.isAccessible()) {
350	                    leakViewField.setAccessible(true);
351	                }
352	                Object obj = leakViewField.get(imm);
353	                if (!(obj instanceof View)) {
354	                    continue;
355	                }
356	                View view = (View) obj;
357	                if (view.getRootView() == window.getDecorView().getRootView()) {
358	                    leakViewField.set(imm, null);
359	                }
360	            } catch (Throwable ignore) {/**/}
361	        }
362	    }
