218	    private static String getMacAddressByNetworkInterface() {
219	        try {
220	            Enumeration<NetworkInterface> nis = NetworkInterface.getNetworkInterfaces();
221	            while (nis.hasMoreElements()) {
222	                NetworkInterface ni = nis.nextElement();
223	                if (ni == null || !ni.getName().equalsIgnoreCase("wlan0")) continue;
224	                byte[] macBytes = ni.getHardwareAddress();
225	                if (macBytes != null && macBytes.length > 0) {
226	                    StringBuilder sb = new StringBuilder();
227	                    for (byte b : macBytes) {
228	                        sb.append(String.format("%02x:", b));
229	                    }
230	                    return sb.substring(0, sb.length() - 1);
231	                }
232	            }
233	        } catch (Exception e) {
234	            e.printStackTrace();
235	        }
236	        return "02:00:00:00:00:00";
237	    }
