240	        try {
241	            InetAddress inetAddress = getInetAddress();
242	            if (inetAddress != null) {
243	                NetworkInterface ni = NetworkInterface.getByInetAddress(inetAddress);
244	                if (ni != null) {
245	                    byte[] macBytes = ni.getHardwareAddress();
246	                    if (macBytes != null && macBytes.length > 0) {
247	                        StringBuilder sb = new StringBuilder();
248	                        for (byte b : macBytes) {
249	                            sb.append(String.format("%02x:", b));
250	                        }
251	                        return sb.substring(0, sb.length() - 1);
252	                    }
253	                }
254	            }
255	        } catch (Exception e) {
256	            e.printStackTrace();
257	        }
258	        return "02:00:00:00:00:00";
259	    }
