261	    private static InetAddress getInetAddress() {
262	        try {
263	            Enumeration<NetworkInterface> nis = NetworkInterface.getNetworkInterfaces();
264	            while (nis.hasMoreElements()) {
265	                NetworkInterface ni = nis.nextElement();
266	                // To prevent phone of xiaomi return "10.0.2.15"
267	                if (!ni.isUp()) continue;
268	                Enumeration<InetAddress> addresses = ni.getInetAddresses();
269	                while (addresses.hasMoreElements()) {
270	                    InetAddress inetAddress = addresses.nextElement();
271	                    if (!inetAddress.isLoopbackAddress()) {
272	                        String hostAddress = inetAddress.getHostAddress();
273	                        if (hostAddress.indexOf(':') < 0) return inetAddress;
274	                    }
275	                }
276	            }
277	        } catch (SocketException e) {
278	            e.printStackTrace();
279	        }
280	        return null;
281	    }
