527	    @RequiresPermission(allOf = {ACCESS_WIFI_STATE, INTERNET, CHANGE_WIFI_STATE})
528	    public static boolean isSameDevice(final String uniqueDeviceId) {
529	        // {prefix}{type}{32id}
530	        if (TextUtils.isEmpty(uniqueDeviceId) && uniqueDeviceId.length() < 33) return false;
531	        if (uniqueDeviceId.equals(udid)) return true;
532	        final String cachedId = UtilsBridge.getSpUtils4Utils().getString(KEY_UDID, null);
533	        if (uniqueDeviceId.equals(cachedId)) return true;
534	        int st = uniqueDeviceId.length() - 33;
535	        String type = uniqueDeviceId.substring(st, st + 1);
536	        if (type.startsWith("1")) {
537	            String macAddress = getMacAddress();
538	            if (macAddress.equals("")) {
539	                return false;
540	            }
541	            return uniqueDeviceId.substring(st + 1).equals(getUdid("", macAddress));
542	        } else if (type.startsWith("2")) {
543	            final String androidId = getAndroidID();
544	            if (TextUtils.isEmpty(androidId)) {
545	                return false;
546	            }
547	            return uniqueDeviceId.substring(st + 1).equals(getUdid("", androidId));
548	        }
549	        return false;
550	    }
