558	    private static String getUdid(String prefix, String id) {
559	        if (id.equals("")) {
560	            return prefix + UUID.randomUUID().toString().replace("-", "");
561	        }
562	        return prefix + UUID.nameUUIDFromBytes(id.getBytes()).toString().replace("-", "");
563	    }
