207	     * Return whether application is running.
208	     *
209	     * @param pkgName The name of the package.
210	     * @return {@code true}: yes<br>{@code false}: no
211	     */
212	    public static boolean isAppRunning(final String pkgName) {
213	        if (UtilsBridge.isSpace(pkgName)) return false;
214	        ActivityManager am = (ActivityManager) Utils.getApp().getSystemService(Context.ACTIVITY_SERVICE);
215	        if (am != null) {
216	            List<ActivityManager.RunningTaskInfo> taskInfo = am.getRunningTasks(Integer.MAX_VALUE);
217	            if (taskInfo != null && taskInfo.size() > 0) {
218	                for (ActivityManager.RunningTaskInfo aInfo : taskInfo) {
219	                    if (aInfo.baseActivity != null) {
220	                        if (pkgName.equals(aInfo.baseActivity.getPackageName())) {
221	                            return true;
222	                        }
223	                    }
224	                }
225	            }
226	            List<ActivityManager.RunningServiceInfo> serviceInfo = am.getRunningServices(Integer.MAX_VALUE);
227	            if (serviceInfo != null && serviceInfo.size() > 0) {
228	                for (ActivityManager.RunningServiceInfo aInfo : serviceInfo) {
229	                    if (pkgName.equals(aInfo.service.getPackageName())) {
230	                        return true;
231	                    }
232	                }
233	            }
234	        }
235	        return false;
236	    }
