799	     * @param listener The progress update listener.
800	     * @return the bytes in file
801	     */
802	    public static byte[] readFile2BytesByStream(final File file,
803	                                                final OnProgressUpdateListener listener) {
804	        if (!UtilsBridge.isFileExists(file)) return null;
805	        try {
806	            ByteArrayOutputStream os = null;
807	            InputStream is = new BufferedInputStream(new FileInputStream(file), sBufferSize);
808	            try {
809	                os = new ByteArrayOutputStream();
810	                byte[] b = new byte[sBufferSize];
811	                int len;
812	                if (listener == null) {
813	                    while ((len = is.read(b, 0, sBufferSize)) != -1) {
814	                        os.write(b, 0, len);
815	                    }
816	                } else {
817	                    double totalSize = is.available();
818	                    int curSize = 0;
819	                    listener.onProgressUpdate(0);
820	                    while ((len = is.read(b, 0, sBufferSize)) != -1) {
821	                        os.write(b, 0, len);
822	                        curSize += len;
823	                        listener.onProgressUpdate(curSize / totalSize);
824	                    }
825	                }
826	                return os.toByteArray();
827	            } catch (IOException e) {
828	                e.printStackTrace();
829	                return null;
830	            } finally {
831	                try {
832	                    is.close();
833	                } catch (IOException e) {
834	                    e.printStackTrace();
835	                }
836	                try {
837	                    if (os != null) {
838	                        os.close();
839	                    }
840	                } catch (IOException e) {
841	                    e.printStackTrace();
842	                }
843	            }
844	        } catch (FileNotFoundException e) {
845	            e.printStackTrace();
846	            return null;
847	        }
848	    }
