184	    private static <T> T getValueByType(final JSONObject jsonObject,
185	                                        final String key,
186	                                        final T defaultValue,
187	                                        final byte type) {
188	        if (jsonObject == null || key == null || key.length() == 0) {
189	            return defaultValue;
190	        }
191	        try {
192	            Object ret;
193	            if (type == TYPE_BOOLEAN) {
194	                ret = jsonObject.getBoolean(key);
195	            } else if (type == TYPE_INT) {
196	                ret = jsonObject.getInt(key);
197	            } else if (type == TYPE_LONG) {
198	                ret = jsonObject.getLong(key);
199	            } else if (type == TYPE_DOUBLE) {
200	                ret = jsonObject.getDouble(key);
201	            } else if (type == TYPE_STRING) {
202	                ret = jsonObject.getString(key);
203	            } else if (type == TYPE_JSON_OBJECT) {
204	                ret = jsonObject.getJSONObject(key);
205	            } else if (type == TYPE_JSON_ARRAY) {
206	                ret = jsonObject.getJSONArray(key);
207	            } else {
208	                return defaultValue;
209	            }
210	            //noinspection unchecked
211	            return (T) ret;
212	        } catch (JSONException e) {
213	            e.printStackTrace();
214	            return defaultValue;
215	        }
216	    }
217	
218	    private static <T> T getValueByType(final String json,
219	                                        final String key,
220	                                        final T defaultValue,
221	                                        final byte type) {
222	        if (json == null || json.length() == 0
223	                || key == null || key.length() == 0) {
224	            return defaultValue;
225	        }
226	        try {
227	            return getValueByType(new JSONObject(json), key, defaultValue, type);
228	        } catch (JSONException e) {
229	            e.printStackTrace();
230	            return defaultValue;
231	        }
232	    }
233	
234	    public static String formatJson(final String json) {
235	        return formatJson(json, 4);
236	    }
237	
238	    public static String formatJson(final String json, final int indentSpaces) {
239	        try {
240	            for (int i = 0, len = json.length(); i < len; i++) {
241	                char c = json.charAt(i);
242	                if (c == '{') {
243	                    return new JSONObject(json).toString(indentSpaces);
244	                } else if (c == '[') {
245	                    return new JSONArray(json).toString(indentSpaces);
246	                } else if (!Character.isWhitespace(c)) {
247	                    return json;
248	                }
249	            }
250	        } catch (JSONException e) {
251	            e.printStackTrace();
252	        }
253	        return json;
254	    }
255	}
