39	     */
40	    public static boolean isEmpty(final Object obj) {
41	        if (obj == null) {
42	            return true;
43	        }
44	        if (obj.getClass().isArray() && Array.getLength(obj) == 0) {
45	            return true;
46	        }
47	        if (obj instanceof CharSequence && obj.toString().length() == 0) {
48	            return true;
49	        }
50	        if (obj instanceof Collection && ((Collection) obj).isEmpty()) {
51	            return true;
52	        }
53	        if (obj instanceof Map && ((Map) obj).isEmpty()) {
54	            return true;
55	        }
56	        if (obj instanceof SimpleArrayMap && ((SimpleArrayMap) obj).isEmpty()) {
57	            return true;
58	        }
59	        if (obj instanceof SparseArray && ((SparseArray) obj).size() == 0) {
60	            return true;
61	        }
62	        if (obj instanceof SparseBooleanArray && ((SparseBooleanArray) obj).size() == 0) {
63	            return true;
64	        }
65	        if (obj instanceof SparseIntArray && ((SparseIntArray) obj).size() == 0) {
66	            return true;
67	        }
68	        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR2) {
69	            if (obj instanceof SparseLongArray && ((SparseLongArray) obj).size() == 0) {
70	                return true;
71	            }
72	        }
73	        if (obj instanceof LongSparseArray && ((LongSparseArray) obj).size() == 0) {
74	            return true;
75	        }
76	        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
77	            if (obj instanceof android.util.LongSparseArray
78	                    && ((android.util.LongSparseArray) obj).size() == 0) {
79	                return true;
80	            }
81	        }
82	        return false;
83	    }
