335	    private Method similarMethod(final String name, final Class<?>[] types)
336	            throws NoSuchMethodException {
337	        Class<?> type = type();
338	        List<Method> methods = new ArrayList<>();
339	        for (Method method : type.getMethods()) {
340	            if (isSimilarSignature(method, name, types)) {
341	                methods.add(method);
342	            }
343	        }
344	        if (!methods.isEmpty()) {
345	            sortMethods(methods);
346	            return methods.get(0);
347	        }
348	        do {
349	            for (Method method : type.getDeclaredMethods()) {
350	                if (isSimilarSignature(method, name, types)) {
351	                    methods.add(method);
352	                }
353	            }
354	            if (!methods.isEmpty()) {
355	                sortMethods(methods);
356	                return methods.get(0);
357	            }
358	            type = type.getSuperclass();
359	        } while (type != null);
360	
361	        throw new NoSuchMethodException("No similar method " + name + " with params "
362	                + Arrays.toString(types) + " could be found on type " + type() + ".");
363	    }
