409	        if (accessible == null) return null;
410	        if (accessible instanceof Member) {
411	            Member member = (Member) accessible;
412	            if (Modifier.isPublic(member.getModifiers())
413	                    && Modifier.isPublic(member.getDeclaringClass().getModifiers())) {
414	                return accessible;
415	            }
416	        }
417	        if (!accessible.isAccessible()) accessible.setAccessible(true);
