444	                        Map<String, Object> map = (Map<String, Object>) object;
445	                        int length = (args == null ? 0 : args.length);
446	
447	                        if (length == 0 && name.startsWith("get")) {
448	                            return map.get(property(name.substring(3)));
449	                        } else if (length == 0 && name.startsWith("is")) {
450	                            return map.get(property(name.substring(2)));
451	                        } else if (length == 1 && name.startsWith("set")) {
452	                            map.put(property(name.substring(3)), args[0]);
453	                            return null;
454	                        }
455	                    }
456	                    throw e;
457	                }
458	            }
459	        };
