185	                                        final String key,
186	                                        final T defaultValue,
187	                                        final byte type) {
188	        if (jsonObject == null || key == null || key.length() == 0) {
189	            return defaultValue;
190	        }
191	        try {
192	            Object ret;
193	            if (type == TYPE_BOOLEAN) {
194	                ret = jsonObject.getBoolean(key);
