196	                ret = jsonObject.getInt(key);
197	            } else if (type == TYPE_LONG) {
198	                ret = jsonObject.getLong(key);
199	            } else if (type == TYPE_DOUBLE) {
200	                ret = jsonObject.getDouble(key);
201	            } else if (type == TYPE_STRING) {
202	                ret = jsonObject.getString(key);
203	            } else if (type == TYPE_JSON_OBJECT) {
204	                ret = jsonObject.getJSONObject(key);
205	            } else if (type == TYPE_JSON_ARRAY) {
206	                ret = jsonObject.getJSONArray(key);
207	            } else {
208	                return defaultValue;
209	            }
210	            //noinspection unchecked
211	            return (T) ret;
