108	    private void registerInner(@Nullable final Object bus) {
109	        if (bus == null) return;
110	        Class<?> aClass = bus.getClass();
111	        String className = aClass.getName();
112	        boolean isNeedRecordTags = false;
113	        synchronized (mClassName_BusesMap) {
114	            Set<Object> buses = mClassName_BusesMap.get(className);
115	            if (buses == null) {
116	                buses = new CopyOnWriteArraySet<>();
117	                mClassName_BusesMap.put(className, buses);
118	                isNeedRecordTags = true;
119	            }
120	            if (buses.contains(bus)) {
121	                Log.w(TAG, "The bus of <" + bus + "> already registered.");
122	                return;
123	            } else {
124	                buses.add(bus);
125	            }
126	        }
127	        if (isNeedRecordTags) {
128	            recordTags(aClass, className);
129	        }
130	        consumeStickyIfExist(bus);
131	    }
132	
133	    private void recordTags(Class<?> aClass, String className) {
134	        List<String> tags = mClassName_TagsMap.get(className);
135	        if (tags == null) {
136	            synchronized (mClassName_TagsMap) {
137	                tags = mClassName_TagsMap.get(className);
138	                if (tags == null) {
139	                    tags = new CopyOnWriteArrayList<>();
140	                    for (Map.Entry<String, List<BusInfo>> entry : mTag_BusInfoListMap.entrySet()) {
141	                        for (BusInfo busInfo : entry.getValue()) {
142	                            try {
143	                                if (Class.forName(busInfo.className).isAssignableFrom(aClass)) {
144	                                    tags.add(entry.getKey());
145	                                    busInfo.subClassNames.add(className);
146	                                }
147	                            } catch (ClassNotFoundException e) {
148	                                e.printStackTrace();
149	                            }
150	                        }
151	                    }
152	                    mClassName_TagsMap.put(className, tags);
153	                }
154	            }
155	        }
156	    }
157	
158	    private void consumeStickyIfExist(final Object bus) {
159	        Map<String, Object> tagArgMap = mClassName_Tag_Arg4StickyMap.get(bus.getClass().getName());
160	        if (tagArgMap == null) return;
161	        synchronized (mClassName_Tag_Arg4StickyMap) {
162	            for (Map.Entry<String, Object> tagArgEntry : tagArgMap.entrySet()) {
163	                consumeSticky(bus, tagArgEntry.getKey(), tagArgEntry.getValue());
164	            }
165	        }
166	    }
167	
168	    private void consumeSticky(final Object bus, final String tag, final Object arg) {
169	        List<BusInfo> busInfoList = mTag_BusInfoListMap.get(tag);
170	        if (busInfoList == null) {
171	            Log.e(TAG, "The bus of tag <" + tag + "> is not exists.");
172	            return;
173	        }
174	        for (BusInfo busInfo : busInfoList) {
175	            if (!busInfo.subClassNames.contains(bus.getClass().getName())) {
176	                continue;
177	            }
178	            if (!busInfo.sticky) {
179	                continue;
180	            }
181	
182	            synchronized (mClassName_Tag_Arg4StickyMap) {
183	                Map<String, Object> tagArgMap = mClassName_Tag_Arg4StickyMap.get(busInfo.className);
184	                if (tagArgMap == null || !tagArgMap.containsKey(tag)) {
185	                    continue;
186	                }
187	                invokeBus(bus, arg, busInfo, true);
188	            }
189	        }
190	    }
191	
192	    private void unregisterInner(final Object bus) {
193	        if (bus == null) return;
194	        String className = bus.getClass().getName();
195	        synchronized (mClassName_BusesMap) {
196	            Set<Object> buses = mClassName_BusesMap.get(className);
197	            if (buses == null || !buses.contains(bus)) {
198	                Log.e(TAG, "The bus of <" + bus + "> was not registered before.");
199	                return;
200	            }
201	            buses.remove(bus);
202	        }
203	    }
