209	    private void postInner(final String tag, final Object arg, final boolean sticky) {
210	        List<BusInfo> busInfoList = mTag_BusInfoListMap.get(tag);
211	        if (busInfoList == null) {
212	            Log.e(TAG, "The bus of tag <" + tag + "> is not exists.");
213	            if (mTag_BusInfoListMap.isEmpty()) {
214	                Log.e(TAG, "Please check whether the bus plugin is applied.");
215	            }
216	            return;
217	        }
218	        for (BusInfo busInfo : busInfoList) {
219	            invokeBus(arg, busInfo, sticky);
220	        }
221	    }
