223	    private void invokeBus(Object arg, BusInfo busInfo, boolean sticky) {
224	        invokeBus(null, arg, busInfo, sticky);
225	    }
226	
227	    private void invokeBus(Object bus, Object arg, BusInfo busInfo, boolean sticky) {
228	        if (busInfo.method == null) {
229	            Method method = getMethodByBusInfo(busInfo);
230	            if (method == null) {
231	                return;
232	            }
233	            busInfo.method = method;
234	        }
235	        invokeMethod(bus, arg, busInfo, sticky);
236	    }
237	
238	    private Method getMethodByBusInfo(BusInfo busInfo) {
239	        try {
240	            if ("".equals(busInfo.paramType)) {
241	                return Class.forName(busInfo.className).getDeclaredMethod(busInfo.funName);
242	            } else {
243	                return Class.forName(busInfo.className).getDeclaredMethod(busInfo.funName, getClassName(busInfo.paramType));
244	            }
245	        } catch (ClassNotFoundException e) {
246	            e.printStackTrace();
247	        } catch (NoSuchMethodException e) {
248	            e.printStackTrace();
249	        }
250	        return null;
251	    }
252	
253	    private Class getClassName(String paramType) throws ClassNotFoundException {
254	        switch (paramType) {
255	            case "boolean":
256	                return boolean.class;
257	            case "int":
258	                return int.class;
259	            case "long":
260	                return long.class;
261	            case "short":
262	                return short.class;
263	            case "byte":
264	                return byte.class;
265	            case "double":
266	                return double.class;
267	            case "float":
268	                return float.class;
269	            case "char":
270	                return char.class;
271	            default:
272	                return Class.forName(paramType);
273	        }
274	    }
275	
276	    private void invokeMethod(final Object arg, final BusInfo busInfo, final boolean sticky) {
277	        invokeMethod(null, arg, busInfo, sticky);
278	    }
279	
280	    private void invokeMethod(final Object bus, final Object arg, final BusInfo busInfo, final boolean sticky) {
281	        Runnable runnable = new Runnable() {
282	            @Override
283	            public void run() {
284	                realInvokeMethod(bus, arg, busInfo, sticky);
285	            }
286	        };
287	        switch (busInfo.threadMode) {
288	            case "MAIN":
289	                ThreadUtils.runOnUiThread(runnable);
290	                return;
291	            case "IO":
292	                ThreadUtils.getIoPool().execute(runnable);
293	                return;
294	            case "CPU":
295	                ThreadUtils.getCpuPool().execute(runnable);
296	                return;
297	            case "CACHED":
298	                ThreadUtils.getCachedPool().execute(runnable);
299	                return;
300	            case "SINGLE":
301	                ThreadUtils.getSinglePool().execute(runnable);
302	                return;
303	            default:
304	                runnable.run();
305	        }
306	    }
307	
308	    private void realInvokeMethod(Object bus, Object arg, BusInfo busInfo, boolean sticky) {
309	        Set<Object> buses = new HashSet<>();
310	        if (bus == null) {
311	            for (String subClassName : busInfo.subClassNames) {
312	                Set<Object> subBuses = mClassName_BusesMap.get(subClassName);
313	                if (subBuses != null && !subBuses.isEmpty()) {
314	                    buses.addAll(subBuses);
315	                }
316	            }
317	            if (buses.size() == 0) {
318	                if (!sticky) {
319	                    Log.e(TAG, "The " + busInfo + " was not registered before.");
320	                }
321	                return;
322	            }
323	        } else {
324	            buses.add(bus);
325	        }
326	        invokeBuses(arg, busInfo, buses);
327	    }
328	
329	    private void invokeBuses(Object arg, BusInfo busInfo, Set<Object> buses) {
330	        try {
331	            if (arg == NULL) {
332	                for (Object bus : buses) {
333	                    busInfo.method.invoke(bus);
334	                }
335	            } else {
336	                for (Object bus : buses) {
337	                    busInfo.method.invoke(bus, arg);
338	                }
339	            }
340	        } catch (IllegalAccessException e) {
341	            e.printStackTrace();
342	        } catch (InvocationTargetException e) {
343	            e.printStackTrace();
344	        }
345	    }
346	
347	    private void postStickyInner(final String tag, final Object arg) {
348	        List<BusInfo> busInfoList = mTag_BusInfoListMap.get(tag);
349	        if (busInfoList == null) {
350	            Log.e(TAG, "The bus of tag <" + tag + "> is not exists.");
351	            return;
352	        }
353	        // 获取多对象，然后消费各个 busInfoList
354	        for (BusInfo busInfo : busInfoList) {
355	            if (!busInfo.sticky) { // not sticky bus will post directly.
356	                invokeBus(arg, busInfo, false);
357	                continue;
358	            }
359	            synchronized (mClassName_Tag_Arg4StickyMap) {
360	                Map<String, Object> tagArgMap = mClassName_Tag_Arg4StickyMap.get(busInfo.className);
361	                if (tagArgMap == null) {
362	                    tagArgMap = new ConcurrentHashMap<>();
363	                    mClassName_Tag_Arg4StickyMap.put(busInfo.className, tagArgMap);
364	                }
365	                tagArgMap.put(tag, arg);
366	            }
367	            invokeBus(arg, busInfo, true);
368	        }
369	    }
370	
371	    private void removeStickyInner(final String tag) {
372	        List<BusInfo> busInfoList = mTag_BusInfoListMap.get(tag);
373	        if (busInfoList == null) {
374	            Log.e(TAG, "The bus of tag <" + tag + "> is not exists.");
375	            return;
376	        }
377	        for (BusInfo busInfo : busInfoList) {
378	            if (!busInfo.sticky) {
