32	    private final List<UiMessageCallback>              mDefensiveCopyList  = new ArrayList<>();
33	
34	    public static UiMessageUtils getInstance() {
35	        return LazyHolder.INSTANCE;
36	    }
37	
38	    private UiMessageUtils() {
39	    }
40	
41	    /**
42	     * Sends an empty Message containing only the message ID.
43	     *
44	     * @param id The message ID.
45	     */
46	    public final void send(final int id) {
47	        mHandler.sendEmptyMessage(id);
48	    }
49	
50	    /**
51	     * Sends a message containing the ID and an arbitrary object.
52	     *
53	     * @param id  The message ID.
54	     * @param obj The object.
55	     */
56	    public final void send(final int id, @NonNull final Object obj) {
57	        mHandler.sendMessage(mHandler.obtainMessage(id, obj));
58	    }
59	
60	    /**
61	     * Add listener for specific type of message by its ID.
62	     * Don't forget to call {@link #removeListener(UiMessageCallback)} or
63	     * {@link #removeListeners(int)}
64	     *
65	     * @param id       The ID of message that will be only notified to listener.
66	     * @param listener The listener.
67	     */
68	    public void addListener(int id, @NonNull final UiMessageCallback listener) {
69	        synchronized (mListenersSpecific) {
70	            List<UiMessageCallback> idListeners = mListenersSpecific.get(id);
71	            if (idListeners == null) {
72	                idListeners = new ArrayList<>();
73	                mListenersSpecific.put(id, idListeners);
74	            }
75	            if (!idListeners.contains(listener)) {
76	                idListeners.add(listener);
77	            }
78	        }
79	    }
80	
81	    /**
82	     * Add listener for all messages.
83	     *
84	     * @param listener The listener.
85	     */
86	    public void addListener(@NonNull final UiMessageCallback listener) {
87	        synchronized (mListenersUniversal) {
88	            if (!mListenersUniversal.contains(listener)) {
89	                mListenersUniversal.add(listener);
90	            } else {
91	                if (DEBUG) {
92	                    Log.w(TAG, "Listener is already added. " + listener.toString());
93	                }
94	            }
95	        }
96	    }
97	
98	    /**
99	     * Remove listener for all messages.
100	     *
101	     * @param listener The listener to remove.
102	     */
103	    public void removeListener(@NonNull final UiMessageCallback listener) {
104	        synchronized (mListenersUniversal) {
105	            if (DEBUG && !mListenersUniversal.contains(listener)) {
106	                Log.w(TAG, "Trying to remove a listener that is not registered. " + listener.toString());
107	            }
108	            mListenersUniversal.remove(listener);
109	        }
110	    }
111	
112	    /**
113	     * Remove all listeners for desired message ID.
114	     *
115	     * @param id The id of the message to stop listening to.
116	     */
117	    public void removeListeners(final int id) {
118	        if (DEBUG) {
119	            final List<UiMessageCallback> callbacks = mListenersSpecific.get(id);
120	            if (callbacks == null || callbacks.size() == 0) {
121	                Log.w(TAG, "Trying to remove specific listeners that are not registered. ID " + id);
122	            }
123	        }
124	        synchronized (mListenersSpecific) {
125	            mListenersSpecific.delete(id);
126	        }
127	    }
128	
129	    /**
130	     * Remove the specific listener for desired message ID.
131	     *
132	     * @param id       The id of the message to stop listening to.
133	     * @param listener The listener which should be removed.
134	     */
135	    public void removeListener(final int id, @NonNull final UiMessageCallback listener) {
136	        synchronized (mListenersSpecific) {
137	            final List<UiMessageCallback> callbacks = this.mListenersSpecific.get(id);
138	            if (callbacks != null && !callbacks.isEmpty()) {
139	                if (DEBUG) {
140	                    if (!callbacks.contains(listener)) {
141	                        Log.w(TAG, "Trying to remove specific listener that is not registered. ID " + id + ", " + listener);
142	                        return;
143	                    }
144	                }
145	                callbacks.remove(listener);
146	            } else {
147	                if (DEBUG) {
148	                    Log.w(TAG, "Trying to remove specific listener that is not registered. ID " + id + ", " + listener);
149	                }
150	            }
151	        }
152	    }
153	
154	    @Override
155	    public boolean handleMessage(Message msg) {
156	        mMessage.setMessage(msg);
157	        if (DEBUG) {
158	            logMessageHandling(mMessage);
159	        }
160	
161	        // process listeners for specified type of message what
162	        synchronized (mListenersSpecific) {
163	            final List<UiMessageCallback> idListeners = mListenersSpecific.get(msg.what);
164	            if (idListeners != null) {
165	                if (idListeners.size() == 0) {
166	                    mListenersSpecific.remove(msg.what);
167	                } else {
168	                    mDefensiveCopyList.addAll(idListeners);
169	                    for (final UiMessageCallback callback : mDefensiveCopyList) {
170	                        callback.handleMessage(mMessage);
171	                    }
172	                    mDefensiveCopyList.clear();
173	                }
174	            }
175	        }
176	
177	        // process universal listeners
178	        synchronized (mListenersUniversal) {
179	            if (mListenersUniversal.size() > 0) {
180	                mDefensiveCopyList.addAll(mListenersUniversal);
181	                for (final UiMessageCallback callback : mDefensiveCopyList) {
182	                    callback.handleMessage(mMessage);
183	                }
184	                mDefensiveCopyList.clear();
185	            }
186	        }
187	
188	        mMessage.setMessage(null);
189	
190	        return true;
191	    }
192	
193	    private void logMessageHandling(@NonNull final UiMessage msg) {
194	        final List<UiMessageCallback> idListeners = mListenersSpecific.get(msg.getId());
195	
196	        if ((idListeners == null || idListeners.size() == 0) && mListenersUniversal.size() == 0) {
197	            Log.w(TAG, "Delivering FAILED for message ID " + msg.getId() + ". No listeners. " + msg.toString());
198	        } else {
199	            final StringBuilder stringBuilder = new StringBuilder();
200	            stringBuilder.append("Delivering message ID ");
201	            stringBuilder.append(msg.getId());
202	            stringBuilder.append(", Specific listeners: ");
203	            if (idListeners == null || idListeners.size() == 0) {
204	                stringBuilder.append(0);
205	            } else {
206	                stringBuilder.append(idListeners.size());
207	                stringBuilder.append(" [");
208	                for (int i = 0; i < idListeners.size(); i++) {
209	                    stringBuilder.append(idListeners.get(i).getClass().getSimpleName());
210	                    if (i < idListeners.size() - 1) {
211	                        stringBuilder.append(",");
212	                    }
213	                }
214	                stringBuilder.append("]");
215	            }
216	
217	            stringBuilder.append(", Universal listeners: ");
218	            synchronized (mListenersUniversal) {
219	                if (mListenersUniversal.size() == 0) {
220	                    stringBuilder.append(0);
221	                } else {
222	                    stringBuilder.append(mListenersUniversal.size());
223	                    stringBuilder.append(" [");
224	                    for (int i = 0; i < mListenersUniversal.size(); i++) {
225	                        stringBuilder.append(mListenersUniversal.get(i).getClass().getSimpleName());
226	                        if (i < mListenersUniversal.size() - 1) {
227	                            stringBuilder.append(",");
228	                        }
229	                    }
230	                    stringBuilder.append("], Message: ");
231	                }
232	            }
233	            stringBuilder.append(msg.toString());
234	
235	            Log.v(TAG, stringBuilder.toString());
236	        }
237	    }
238	
239	    public static final class UiMessage {
240	
241	        private Message mMessage;
242	
243	        private UiMessage(final Message message) {
244	            this.mMessage = message;
245	        }
246	
247	        private void setMessage(final Message message) {
248	            mMessage = message;
249	        }
250	
251	        public int getId() {
252	            return mMessage.what;
253	        }
254	
255	        public Object getObject() {
256	            return mMessage.obj;
257	        }
258	
259	        @Override
260	        public String toString() {
261	            return "{ " +
262	                    "id=" + getId() +
263	                    ", obj=" + getObject() +
264	                    " }";
265	        }
266	    }
267	
268	    public interface UiMessageCallback {
269	        void handleMessage(@NonNull UiMessage localMessage);
270	    }
271	
272	    private static final class LazyHolder {
273	        private static final UiMessageUtils INSTANCE = new UiMessageUtils();
274	    }
275	}
