40	public class MessengerUtils {
41	
42	    private static ConcurrentHashMap<String, MessageCallback> subscribers = new ConcurrentHashMap<>();
43	
44	    private static Map<String, Client> sClientMap = new HashMap<>();
45	    private static Client              sLocalClient;
46	
47	    private static final int    WHAT_SUBSCRIBE   = 0x00;
48	    private static final int    WHAT_UNSUBSCRIBE = 0x01;
49	    private static final int    WHAT_SEND        = 0x02;
50	    private static final String KEY_STRING       = "MESSENGER_UTILS";
51	
52	    public static void register() {
53	        if (UtilsBridge.isMainProcess()) {
54	            if (UtilsBridge.isServiceRunning(ServerService.class.getName())) {
55	                Log.i("MessengerUtils", "Server service is running.");
56	                return;
