59	            return;
60	        }
61	        if (sLocalClient == null) {
62	            Client client = new Client(null);
63	            if (client.bind()) {
64	                sLocalClient = client;
65	            } else {
66	                Log.e("MessengerUtils", "Bind service failed.");
67	            }
68	        } else {
69	            Log.i("MessengerUtils", "The client have been bind.");
70	        }
71	    }
72	
73	    public static void unregister() {
74	        if (UtilsBridge.isMainProcess()) {
75	            if (!UtilsBridge.isServiceRunning(ServerService.class.getName())) {
76	                Log.i("MessengerUtils", "Server service isn't running.");
77	                return;
78	            }
79	            Intent intent = new Intent(Utils.getApp(), ServerService.class);
80	            Utils.getApp().stopService(intent);
81	        }
82	        if (sLocalClient != null) {
83	            sLocalClient.unbind();
84	        }
85	    }
86	
87	    public static void register(final String pkgName) {
88	        if (sClientMap.containsKey(pkgName)) {
89	            Log.i("MessengerUtils", "register: client registered: " + pkgName);
90	            return;
91	        }
92	        Client client = new Client(pkgName);
93	        if (client.bind()) {
94	            sClientMap.put(pkgName, client);
95	        } else {
96	            Log.e("MessengerUtils", "register: client bind failed: " + pkgName);
97	        }
98	    }
99	
100	    public static void unregister(final String pkgName) {
101	        if (!sClientMap.containsKey(pkgName)) {
102	            Log.i("MessengerUtils", "unregister: client didn't register: " + pkgName);
103	            return;
104	        }
105	        Client client = sClientMap.get(pkgName);
106	        sClientMap.remove(pkgName);
107	        if (client != null) {
108	            client.unbind();
109	        }
110	    }
111	
112	    public static void subscribe(@NonNull final String key, @NonNull final MessageCallback callback) {
113	        subscribers.put(key, callback);
114	    }
115	
116	    public static void unsubscribe(@NonNull final String key) {
117	        subscribers.remove(key);
