119	
120	    public static void post(@NonNull String key, @NonNull Bundle data) {
121	        data.putString(KEY_STRING, key);
122	        if (sLocalClient != null) {
123	            sLocalClient.sendMsg2Server(data);
124	        } else {
125	            Intent intent = new Intent(Utils.getApp(), ServerService.class);
126	            intent.putExtras(data);
127	            startServiceCompat(intent);
128	        }
129	        for (Client client : sClientMap.values()) {
