131	        }
132	    }
133	
134	    private static void startServiceCompat(Intent intent) {
135	        try {
136	            intent.setFlags(Intent.FLAG_INCLUDE_STOPPED_PACKAGES);
137	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
138	                Utils.getApp().startForegroundService(intent);
139	            } else {
140	                Utils.getApp().startService(intent);
141	            }
142	        } catch (Exception e) {
143	            e.printStackTrace();
144	        }
145	    }
146	
147	    static class Client {
148	
149	        String             mPkgName;
150	        Messenger          mServer;
151	        LinkedList<Bundle> mCached = new LinkedList<>();
152	        @SuppressLint("HandlerLeak")
153	        Handler mReceiveServeMsgHandler = new Handler() {
154	            @Override
155	            public void handleMessage(Message msg) {
156	                Bundle data = msg.getData();
157	                data.setClassLoader(MessengerUtils.class.getClassLoader());
158	                String key = data.getString(KEY_STRING);
159	                if (key != null) {
160	                    MessageCallback callback = subscribers.get(key);
161	                    if (callback != null) {
162	                        callback.messageCall(data);
163	                    }
164	                }
165	            }
166	        };
167	        Messenger         mClient = new Messenger(mReceiveServeMsgHandler);
168	        ServiceConnection mConn   = new ServiceConnection() {
169	
170	            @Override
171	            public void onServiceConnected(ComponentName name, IBinder service) {
172	                Log.d("MessengerUtils", "client service connected " + name);
173	                mServer = new Messenger(service);
174	                int key = UtilsBridge.getCurrentProcessName().hashCode();
175	                Message msg = Message.obtain(mReceiveServeMsgHandler, WHAT_SUBSCRIBE, key, 0);
176	                msg.getData().setClassLoader(MessengerUtils.class.getClassLoader());
177	                msg.replyTo = mClient;
178	                try {
179	                    mServer.send(msg);
180	                } catch (RemoteException e) {
181	                    e.printStackTrace();
182	                }
183	                sendCachedMsg2Server();
184	            }
185	
186	            @Override
187	            public void onServiceDisconnected(ComponentName name) {
188	                Log.w("MessengerUtils", "client service disconnected:" + name);
189	                mServer = null;
190	                if (!bind()) {
191	                    Log.e("MessengerUtils", "client service rebind failed: " + name);
192	                }
193	            }
194	        };
195	
196	        Client(String pkgName) {
197	            this.mPkgName = pkgName;
198	        }
199	
200	        boolean bind() {
201	            if (TextUtils.isEmpty(mPkgName)) {
202	                Intent intent = new Intent(Utils.getApp(), ServerService.class);
203	                return Utils.getApp().bindService(intent, mConn, Context.BIND_AUTO_CREATE);
204	            }
205	            if (UtilsBridge.isAppInstalled(mPkgName)) {
206	                if (UtilsBridge.isAppRunning(mPkgName)) {
207	                    Intent intent = new Intent(mPkgName + ".messenger");
208	                    intent.setPackage(mPkgName);
209	                    return Utils.getApp().bindService(intent, mConn, Context.BIND_AUTO_CREATE);
210	                } else {
211	                    Log.e("MessengerUtils", "bind: the app is not running -> " + mPkgName);
212	                    return false;
213	                }
214	            } else {
215	                Log.e("MessengerUtils", "bind: the app is not installed -> " + mPkgName);
216	                return false;
217	            }
218	        }
219	
220	        void unbind() {
221	            int key = UtilsBridge.getCurrentProcessName().hashCode();
222	            Message msg = Message.obtain(mReceiveServeMsgHandler, WHAT_UNSUBSCRIBE, key, 0);
223	            msg.replyTo = mClient;
224	            try {
225	                mServer.send(msg);
226	            } catch (RemoteException e) {
227	                e.printStackTrace();
228	            }
229	            try {
230	                Utils.getApp().unbindService(mConn);
231	            } catch (Exception ignore) {/*ignore*/}
232	        }
233	
234	        void sendMsg2Server(Bundle bundle) {
235	            if (mServer == null) {
236	                mCached.addFirst(bundle);
237	                Log.i("MessengerUtils", "save the bundle " + bundle);
238	            } else {
239	                sendCachedMsg2Server();
240	                if (!send2Server(bundle)) {
241	                    mCached.addFirst(bundle);
242	                }
243	            }
244	        }
245	
246	        private void sendCachedMsg2Server() {
247	            if (mCached.isEmpty()) return;
248	            for (int i = mCached.size() - 1; i >= 0; --i) {
249	                if (send2Server(mCached.get(i))) {
250	                    mCached.remove(i);
251	                }
252	            }
253	        }
254	
255	        private boolean send2Server(Bundle bundle) {
256	            Message msg = Message.obtain(mReceiveServeMsgHandler, WHAT_SEND);
257	            bundle.setClassLoader(MessengerUtils.class.getClassLoader());
258	            msg.setData(bundle);
259	            msg.replyTo = mClient;
260	            try {
261	                mServer.send(msg);
262	                return true;
263	            } catch (RemoteException e) {
264	                e.printStackTrace();
265	                return false;
266	            }
267	        }
268	    }
269	
270	    public static class ServerService extends Service {
271	
272	        private final ConcurrentHashMap<Integer, Messenger> mClientMap = new ConcurrentHashMap<>();
273	
274	        @SuppressLint("HandlerLeak")
275	        private final Handler mReceiveClientMsgHandler = new Handler() {
276	            @Override
277	            public void handleMessage(Message msg) {
278	                switch (msg.what) {
279	                    case WHAT_SUBSCRIBE:
280	                        mClientMap.put(msg.arg1, msg.replyTo);
281	                        break;
282	                    case WHAT_SEND:
283	                        sendMsg2Client(msg);
284	                        consumeServerProcessCallback(msg);
285	                        break;
286	                    case WHAT_UNSUBSCRIBE:
287	                        mClientMap.remove(msg.arg1);
288	                        break;
289	                    default:
290	                        super.handleMessage(msg);
291	                }
292	            }
293	        };
294	
295	        private final Messenger messenger = new Messenger(mReceiveClientMsgHandler);
296	
297	        @Nullable
298	        @Override
299	        public IBinder onBind(Intent intent) {
300	            return messenger.getBinder();
301	        }
302	
303	        @Override
304	        public int onStartCommand(Intent intent, int flags, int startId) {
305	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
306	                Notification notification = UtilsBridge.getNotification(
307	                        NotificationUtils.ChannelConfig.DEFAULT_CHANNEL_CONFIG, null
308	                );
309	                startForeground(1, notification);
310	            }
311	            if (intent != null) {
312	                Bundle extras = intent.getExtras();
313	                if (extras != null) {
314	                    Message msg = Message.obtain(mReceiveClientMsgHandler, WHAT_SEND);
315	                    msg.replyTo = messenger;
316	                    msg.setData(extras);
317	                    sendMsg2Client(msg);
318	                    consumeServerProcessCallback(msg);
319	                }
320	            }
321	            return START_NOT_STICKY;
322	        }
323	
324	        private void sendMsg2Client(final Message msg) {
325	           final Message obtain = Message.obtain(msg); //Copy the original
326	            for (Messenger client : mClientMap.values()) {
327	                try {
328	                    if (client != null) {
329	                        client.send(Message.obtain(obtain));
330	                    }
331	                } catch (RemoteException e) {
332	                    e.printStackTrace();
333	                }
334	            }
335	            obtain.recycle(); //Recycled copy
336	        }
337	
338	        private void consumeServerProcessCallback(final Message msg) {
339	            Bundle data = msg.getData();
340	            if (data != null) {
341	                String key = data.getString(KEY_STRING);
342	                if (key != null) {
343	                    MessageCallback callback = subscribers.get(key);
344	                    if (callback != null) {
345	                        callback.messageCall(data);
346	                    }
347	                }
348	            }
349	        }
350	    }
351	
352	    public interface MessageCallback {
353	        void messageCall(Bundle data);
354	    }
355	}
