100	    private static void applyDisplayMetrics(@NonNull final Resources resources, final float newXdpi) {
101	        resources.getDisplayMetrics().xdpi = newXdpi;
102	        Utils.getApp().getResources().getDisplayMetrics().xdpi = newXdpi;
103	        applyOtherDisplayMetrics(resources, newXdpi);
104	    }
105	
106	    static Runnable getPreLoadRunnable() {
107	        return new Runnable() {
108	            @Override
109	            public void run() {
110	                preLoad();
111	            }
112	        };
113	    }
114	
115	    private static void preLoad() {
116	        applyDisplayMetrics(Resources.getSystem(), Resources.getSystem().getDisplayMetrics().xdpi);
117	    }
118	
119	    private static void applyOtherDisplayMetrics(final Resources resources, final float newXdpi) {
120	        if (sMetricsFields == null) {
121	            sMetricsFields = new ArrayList<>();
122	            Class resCls = resources.getClass();
123	            Field[] declaredFields = resCls.getDeclaredFields();
124	            while (declaredFields != null && declaredFields.length > 0) {
125	                for (Field field : declaredFields) {
126	                    if (field.getType().isAssignableFrom(DisplayMetrics.class)) {
127	                        field.setAccessible(true);
128	                        DisplayMetrics tmpDm = getMetricsFromField(resources, field);
129	                        if (tmpDm != null) {
130	                            sMetricsFields.add(field);
131	                            tmpDm.xdpi = newXdpi;
132	                        }
133	                    }
134	                }
135	                resCls = resCls.getSuperclass();
136	                if (resCls != null) {
137	                    declaredFields = resCls.getDeclaredFields();
138	                } else {
139	                    break;
140	                }
141	            }
142	        } else {
143	            applyMetricsFields(resources, newXdpi);
144	        }
145	    }
146	
147	    private static void applyMetricsFields(final Resources resources, final float newXdpi) {
148	        for (Field metricsField : sMetricsFields) {
149	            try {
150	                DisplayMetrics dm = (DisplayMetrics) metricsField.get(resources);
151	                if (dm != null) dm.xdpi = newXdpi;
152	            } catch (Exception e) {
153	                e.printStackTrace();
154	            }
155	        }
156	    }
157	
158	    private static DisplayMetrics getMetricsFromField(final Resources resources, final Field field) {
159	        try {
160	            return (DisplayMetrics) field.get(resources);
161	        } catch (Exception ignore) {
162	            return null;
163	        }
164	    }
165	}
