25	    /**
26	     * Join the path.
27	     *
28	     * @param parent The parent of path.
29	     * @param child  The child path.
30	     * @return the path
31	     */
32	    public static String join(String parent, String child) {
33	        if (TextUtils.isEmpty(child)) return parent;
34	        if (parent == null) {
35	            parent = "";
36	        }
37	        int len = parent.length();
38	        String legalSegment = getLegalSegment(child);
39	        String newPath;
40	        if (len == 0) {
41	            newPath = SEP + legalSegment;
42	        } else if (parent.charAt(len - 1) == SEP) {
43	            newPath = parent + legalSegment;
44	        } else {
45	            newPath = parent + SEP + legalSegment;
46	        }
47	        return newPath;
48	    }
49	
50	    private static String getLegalSegment(String segment) {
51	        int st = -1, end = -1;
52	        char[] charArray = segment.toCharArray();
53	        for (int i = 0; i < charArray.length; i++) {
54	            char c = charArray[i];
55	            if (c != SEP) {
56	                if (st == -1) {
57	                    st = i;
58	                }
59	                end = i;
60	            }
61	        }
62	        if (st >= 0 && end >= st) {
63	            return segment.substring(st, end + 1);
64	        }
65	        throw new IllegalArgumentException("segment of <" + segment + "> is illegal");
66	    }
