47	    /**
48	     * Return the foreground process name.
49	     * <p>Target APIs greater than 21 must hold
50	     * {@code <uses-permission android:name="android.permission.PACKAGE_USAGE_STATS" />}</p>
51	     *
52	     * @return the foreground process name
53	     */
54	    public static String getForegroundProcessName() {
55	        ActivityManager am =
56	                (ActivityManager) Utils.getApp().getSystemService(Context.ACTIVITY_SERVICE);
57	        //noinspection ConstantConditions
58	        List<ActivityManager.RunningAppProcessInfo> pInfo = am.getRunningAppProcesses();
59	        if (pInfo != null && pInfo.size() > 0) {
60	            for (ActivityManager.RunningAppProcessInfo aInfo : pInfo) {
61	                if (aInfo.importance
62	                        == ActivityManager.RunningAppProcessInfo.IMPORTANCE_FOREGROUND) {
63	                    return aInfo.processName;
64	                }
65	            }
66	        }
67	        if (android.os.Build.VERSION.SDK_INT > android.os.Build.VERSION_CODES.LOLLIPOP) {
68	            PackageManager pm = Utils.getApp().getPackageManager();
69	            Intent intent = new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS);
70	            List<ResolveInfo> list =
71	                    pm.queryIntentActivities(intent, PackageManager.MATCH_DEFAULT_ONLY);
72	            Log.i("ProcessUtils", list.toString());
73	            if (list.size() <= 0) {
74	                Log.i("ProcessUtils",
75	                        "getForegroundProcessName: noun of access to usage information.");
76	                return "";
77	            }
78	            try {// Access to usage information.
79	                ApplicationInfo info =
80	                        pm.getApplicationInfo(Utils.getApp().getPackageName(), 0);
81	                AppOpsManager aom =
82	                        (AppOpsManager) Utils.getApp().getSystemService(Context.APP_OPS_SERVICE);
83	                if (aom.checkOpNoThrow(AppOpsManager.OPSTR_GET_USAGE_STATS,
84	                        info.uid,
85	                        info.packageName) != AppOpsManager.MODE_ALLOWED) {
86	                    intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
87	                    Utils.getApp().startActivity(intent);
88	                }
89	                if (aom.checkOpNoThrow(AppOpsManager.OPSTR_GET_USAGE_STATS,
90	                        info.uid,
91	                        info.packageName) != AppOpsManager.MODE_ALLOWED) {
92	                    Log.i("ProcessUtils",
93	                            "getForegroundProcessName: refuse to device usage stats.");
94	                    return "";
95	                }
96	                UsageStatsManager usageStatsManager = (UsageStatsManager) Utils.getApp()
97	                        .getSystemService(Context.USAGE_STATS_SERVICE);
98	                List<UsageStats> usageStatsList = null;
99	                if (usageStatsManager != null) {
100	                    long endTime = System.currentTimeMillis();
101	                    long beginTime = endTime - 86400000 * 7;
102	                    usageStatsList = usageStatsManager
103	                            .queryUsageStats(UsageStatsManager.INTERVAL_BEST,
104	                                    beginTime, endTime);
105	                }
106	                if (usageStatsList == null || usageStatsList.isEmpty()) return "";
107	                UsageStats recentStats = null;
108	                for (UsageStats usageStats : usageStatsList) {
109	                    if (recentStats == null
110	                            || usageStats.getLastTimeUsed() > recentStats.getLastTimeUsed()) {
111	                        recentStats = usageStats;
112	                    }
113	                }
114	                return recentStats == null ? null : recentStats.getPackageName();
115	            } catch (PackageManager.NameNotFoundException e) {
116	                e.printStackTrace();
117	            }
118	        }
119	        return "";
120	    }
