221	    private static String getCurrentProcessNameByFile() {
222	        try {
223	            File file = new File("/proc/" + android.os.Process.myPid() + "/" + "cmdline");
224	            BufferedReader mBufferedReader = new BufferedReader(new FileReader(file));
225	            String processName = mBufferedReader.readLine().trim();
226	            mBufferedReader.close();
