234	    private static String getCurrentProcessNameByAms() {
235	        try {
236	            ActivityManager am = (ActivityManager) Utils.getApp().getSystemService(Context.ACTIVITY_SERVICE);
237	            if (am == null) return "";
238	            List<ActivityManager.RunningAppProcessInfo> info = am.getRunningAppProcesses();
239	            if (info == null || info.size() == 0) return "";
240	            int pid = android.os.Process.myPid();
241	            for (ActivityManager.RunningAppProcessInfo aInfo : info) {
242	                if (aInfo.pid == pid) {
243	                    if (aInfo.processName != null) {
244	                        return aInfo.processName;
245	                    }
246	                }
247	            }
248	        } catch (Exception e) {
249	            return "";
250	        }
251	        return "";
252	    }
