254	    private static String getCurrentProcessNameByReflect() {
255	        String processName = "";
256	        try {
257	            Application app = Utils.getApp();
258	            Field loadedApkField = app.getClass().getField("mLoadedApk");
259	            loadedApkField.setAccessible(true);
260	            Object loadedApk = loadedApkField.get(app);
261	
262	            Field activityThreadField = loadedApk.getClass().getDeclaredField("mActivityThread");
263	            activityThreadField.setAccessible(true);
264	            Object activityThread = activityThreadField.get(loadedApk);
265	
266	            Method getProcessName = activityThread.getClass().getDeclaredMethod("getProcessName");
267	            processName = (String) getProcessName.invoke(activityThread);
268	        } catch (Exception e) {
269	            e.printStackTrace();
270	        }
271	        return processName;
272	    }
