50	    /**
51	     * Return the information of sdcard.
52	     *
53	     * @return the information of sdcard
54	     */
55	    public static List<SDCardInfo> getSDCardInfo() {
56	        List<SDCardInfo> paths = new ArrayList<>();
57	        StorageManager sm = (StorageManager) Utils.getApp().getSystemService(Context.STORAGE_SERVICE);
58	        if (sm == null) return paths;
59	        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.N) {
60	            List<StorageVolume> storageVolumes = sm.getStorageVolumes();
61	            try {
62	                //noinspection JavaReflectionMemberAccess
63	                Method getPathMethod = StorageVolume.class.getMethod("getPath");
64	                for (StorageVolume storageVolume : storageVolumes) {
65	                    boolean isRemovable = storageVolume.isRemovable();
66	                    String state = storageVolume.getState();
67	                    String path = (String) getPathMethod.invoke(storageVolume);
68	                    paths.add(new SDCardInfo(path, state, isRemovable));
69	                }
70	            } catch (NoSuchMethodException e) {
71	                e.printStackTrace();
72	            } catch (IllegalAccessException e) {
73	                e.printStackTrace();
74	            } catch (InvocationTargetException e) {
75	                e.printStackTrace();
76	            }
77	        } else {
78	            try {
79	                Class<?> storageVolumeClazz = Class.forName("android.os.storage.StorageVolume");
80	                //noinspection JavaReflectionMemberAccess
81	                Method getPathMethod = storageVolumeClazz.getMethod("getPath");
82	                Method isRemovableMethod = storageVolumeClazz.getMethod("isRemovable");
83	                //noinspection JavaReflectionMemberAccess
84	                Method getVolumeStateMethod = StorageManager.class.getMethod("getVolumeState", String.class);
85	                //noinspection JavaReflectionMemberAccess
86	                Method getVolumeListMethod = StorageManager.class.getMethod("getVolumeList");
87	                Object result = getVolumeListMethod.invoke(sm);
88	                final int length = Array.getLength(result);
89	                for (int i = 0; i < length; i++) {
90	                    Object storageVolumeElement = Array.get(result, i);
91	                    String path = (String) getPathMethod.invoke(storageVolumeElement);
92	                    boolean isRemovable = (Boolean) isRemovableMethod.invoke(storageVolumeElement);
93	                    String state = (String) getVolumeStateMethod.invoke(sm, path);
94	                    paths.add(new SDCardInfo(path, state, isRemovable));
95	                }
96	            } catch (ClassNotFoundException e) {
97	                e.printStackTrace();
98	            } catch (InvocationTargetException e) {
99	                e.printStackTrace();
100	            } catch (NoSuchMethodException e) {
101	                e.printStackTrace();
102	            } catch (IllegalAccessException e) {
103	                e.printStackTrace();
