198	    /**
199	     * Show the snackbar.
200	     *
201	     * @param isShowTop True to show the snack bar on the top, false otherwise.
202	     */
203	    public Snackbar show(boolean isShowTop) {
204	        View view = this.view;
205	        if (view == null) return null;
206	        if (isShowTop) {
207	            ViewGroup suitableParent = findSuitableParentCopyFromSnackbar(view);
208	            View topSnackBarContainer = suitableParent.findViewWithTag("topSnackBarCoordinatorLayout");
209	            if (topSnackBarContainer == null) {
210	                CoordinatorLayout topSnackBarCoordinatorLayout = new CoordinatorLayout(view.getContext());
211	                topSnackBarCoordinatorLayout.setTag("topSnackBarCoordinatorLayout");
212	                topSnackBarCoordinatorLayout.setRotation(180);
213	                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
214	                    // bring to front
215	                    topSnackBarCoordinatorLayout.setElevation(100);
216	                }
217	                suitableParent.addView(topSnackBarCoordinatorLayout, ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT);
218	                topSnackBarContainer = topSnackBarCoordinatorLayout;
219	            }
220	            view = topSnackBarContainer;
221	        }
222	        if (messageColor != COLOR_DEFAULT) {
223	            SpannableString spannableString = new SpannableString(message);
224	            ForegroundColorSpan colorSpan = new ForegroundColorSpan(messageColor);
225	            spannableString.setSpan(
226	                    colorSpan, 0, spannableString.length(), Spanned.SPAN_EXCLUSIVE_EXCLUSIVE
227	            );
228	            sWeakSnackbar = new WeakReference<>(Snackbar.make(view, spannableString, duration));
229	        } else {
230	            sWeakSnackbar = new WeakReference<>(Snackbar.make(view, message, duration));
231	        }
232	        final Snackbar snackbar = sWeakSnackbar.get();
233	        final Snackbar.SnackbarLayout snackbarView = (Snackbar.SnackbarLayout) snackbar.getView();
234	        if (isShowTop) {
235	            for (int i = 0; i < snackbarView.getChildCount(); i++) {
236	                View child = snackbarView.getChildAt(i);
237	                child.setRotation(180);
238	            }
239	        }
240	        if (bgResource != -1) {
241	            snackbarView.setBackgroundResource(bgResource);
242	        } else if (bgColor != COLOR_DEFAULT) {
243	            snackbarView.setBackgroundColor(bgColor);
244	        }
245	        if (bottomMargin != 0) {
246	            ViewGroup.MarginLayoutParams params =
247	                    (ViewGroup.MarginLayoutParams) snackbarView.getLayoutParams();
248	            params.bottomMargin = bottomMargin;
249	        }
250	        if (actionText.length() > 0 && actionListener != null) {
251	            if (actionTextColor != COLOR_DEFAULT) {
252	                snackbar.setActionTextColor(actionTextColor);
253	            }
254	            snackbar.setAction(actionText, actionListener);
255	        }
256	        snackbar.show();
257	        return snackbar;
258	    }
