  3	import android.content.res.Resources;
  4	import android.util.DisplayMetrics;
  5	import android.util.TypedValue;
  6	import android.view.View;
  7	import android.view.ViewGroup;
  8	
  9	/**
 10	 * <pre>
 11	 *     author: Blankj
 12	 *     blog  : http://blankj.com
 13	 *     time  : 2016/08/02
 14	 *     desc  : utils about size
 15	 * </pre>
 16	 */
 17	public final class SizeUtils {
 18	
 19	    private SizeUtils() {
 20	        throw new UnsupportedOperationException("u can't instantiate me...");
 21	    }
 22	
 23	    /**
 24	     * Value of dp to value of px.
 25	     *
 26	     * @param dpValue The value of dp.
 27	     * @return value of px
 28	     */
 29	    public static int dp2px(final float dpValue) {
 30	        final float scale = Resources.getSystem().getDisplayMetrics().density;
 31	        return (int) (dpValue * scale + 0.5f);
 32	    }
 33	
 34	    /**
 35	     * Value of px to value of dp.
 36	     *
 37	     * @param pxValue The value of px.
 38	     * @return value of dp
 39	     */
 40	    public static int px2dp(final float pxValue) {
 41	        final float scale = Resources.getSystem().getDisplayMetrics().density;
 42	        return (int) (pxValue / scale + 0.5f);
 43	    }
 44	
 45	    /**
 46	     * Value of sp to value of px.
 47	     *
 48	     * @param spValue The value of sp.
 49	     * @return value of px
 50	     */
 51	    public static int sp2px(final float spValue) {
 52	        final float fontScale = Resources.getSystem().getDisplayMetrics().scaledDensity;
 53	        return (int) (spValue * fontScale + 0.5f);
 54	    }
 55	
 56	    /**
 57	     * Value of px to value of sp.
 58	     *
 59	     * @param pxValue The value of px.
 60	     * @return value of sp
 61	     */
 62	    public static int px2sp(final float pxValue) {
 63	        final float fontScale = Resources.getSystem().getDisplayMetrics().scaledDensity;
 64	        return (int) (pxValue / fontScale + 0.5f);
 65	    }
 66	
 67	    /**
 68	     * Converts an unpacked complex data value holding a dimension to its final floating
 69	     * point value. The two parameters <var>unit</var> and <var>value</var>
 70	     * are as in {@link TypedValue#TYPE_DIMENSION}.
 71	     *
 72	     * @param value The value to apply the unit to.
 73	     * @param unit  The unit to convert from.
 74	     * @return The complex floating point value multiplied by the appropriate
 75	     * metrics depending on its unit.
 76	     */
 77	    public static float applyDimension(final float value, final int unit) {
 78	        DisplayMetrics metrics = Resources.getSystem().getDisplayMetrics();
 79	        switch (unit) {
 80	            case TypedValue.COMPLEX_UNIT_PX:
 81	                return value;
 82	            case TypedValue.COMPLEX_UNIT_DIP:
 83	                return value * metrics.density;
 84	            case TypedValue.COMPLEX_UNIT_SP:
 85	                return value * metrics.scaledDensity;
 86	            case TypedValue.COMPLEX_UNIT_PT:
 87	                return value * metrics.xdpi * (1.0f / 72);
 88	            case TypedValue.COMPLEX_UNIT_IN:
 89	                return value * metrics.xdpi;
 90	            case TypedValue.COMPLEX_UNIT_MM:
 91	                return value * metrics.xdpi * (1.0f / 25.4f);
 92	        }
 93	        return 0;
 94	    }
 95	
 96	    /**
 97	     * Force get the size of view.
 98	     * <p>e.g.</p>
 99	     * <pre>
100	     * SizeUtils.forceGetViewSize(view, new SizeUtils.OnGetSizeListener() {
101	     *     Override
102	     *     public void onGetSize(final View view) {
103	     *         view.getWidth();
104	     *     }
105	     * });
106	     * </pre>
107	     *
108	     * @param view     The view.
109	     * @param listener The get size listener.
110	     */
111	    public static void forceGetViewSize(final View view, final OnGetSizeListener listener) {
112	        view.post(new Runnable() {
113	            @Override
114	            public void run() {
115	                if (listener != null) {
116	                    listener.onGetSize(view);
117	                }
118	            }
119	        });
120	    }
121	
122	    /**
123	     * Return the width of view.
124	     *
125	     * @param view The view.
126	     * @return the width of view
127	     */
128	    public static int getMeasuredWidth(final View view) {
129	        return measureView(view)[0];
130	    }
131	
132	    /**
133	     * Return the height of view.
134	     *
135	     * @param view The view.
136	     * @return the height of view
137	     */
138	    public static int getMeasuredHeight(final View view) {
139	        return measureView(view)[1];
140	    }
141	
142	    /**
143	     * Measure the view.
144	     *
145	     * @param view The view.
146	     * @return arr[0]: view's width, arr[1]: view's height
147	     */
148	    public static int[] measureView(final View view) {
149	        ViewGroup.LayoutParams lp = view.getLayoutParams();
150	        if (lp == null) {
151	            lp = new ViewGroup.LayoutParams(
152	                    ViewGroup.LayoutParams.MATCH_PARENT,
153	                    ViewGroup.LayoutParams.WRAP_CONTENT
154	            );
155	        }
156	        int widthSpec = ViewGroup.getChildMeasureSpec(0, 0, lp.width);
157	        int lpHeight = lp.height;
158	        int heightSpec;
159	        if (lpHeight > 0) {
160	            heightSpec = View.MeasureSpec.makeMeasureSpec(lpHeight, View.MeasureSpec.EXACTLY);
161	        } else {
162	            heightSpec = View.MeasureSpec.makeMeasureSpec(0, View.MeasureSpec.UNSPECIFIED);
163	        }
164	        view.measure(widthSpec, heightSpec);
165	        return new int[]{view.getMeasuredWidth(), view.getMeasuredHeight()};
166	    }
167	
168	    ///////////////////////////////////////////////////////////////////////////
169	    // interface
170	    ///////////////////////////////////////////////////////////////////////////
171	
172	    public interface OnGetSizeListener {
173	        void onGetSize(View view);
174	    }
175	}
