 69	    private static void applyLanguageReal(final Locale locale,
 70	                                          final boolean isRelaunchApp) {
 71	        if (locale == null) {
 72	            UtilsBridge.getSpUtils4Utils().put(KEY_LOCALE, VALUE_FOLLOW_SYSTEM, true);
 73	        } else {
 74	            UtilsBridge.getSpUtils4Utils().put(KEY_LOCALE, locale2String(locale), true);
 75	        }
 76	
 77	        Locale destLocal = locale == null ? getLocal(Resources.getSystem().getConfiguration()) : locale;
 78	        updateAppContextLanguage(destLocal, new Utils.Consumer<Boolean>() {
 79	            @Override
 80	            public void accept(Boolean success) {
 81	                if (success) {
 82	                    restart(isRelaunchApp);
 83	                } else {
 84	                    // use relaunch app
 85	                    UtilsBridge.relaunchApp();
 86	                }
 87	            }
 88	        });
 89	    }
