 91	    private static void restart(final boolean isRelaunchApp) {
 92	        if (isRelaunchApp) {
 93	            UtilsBridge.relaunchApp();
 94	        } else {
 95	            for (Activity activity : UtilsBridge.getActivityList()) {
 96	                activity.recreate();
