164	    /**
165	     * Update the locale of applicationContext.
166	     *
167	     * @param destLocale The dest locale.
168	     * @param consumer   The consumer.
169	     */
170	    public static void updateAppContextLanguage(@NonNull Locale destLocale, @Nullable Utils.Consumer<Boolean> consumer) {
171	        pollCheckAppContextLocal(destLocale, 0, consumer);
172	    }
173	
174	    static void pollCheckAppContextLocal(final Locale destLocale, final int index, final Utils.Consumer<Boolean> consumer) {
175	        Resources appResources = Utils.getApp().getResources();
176	        Configuration appConfig = appResources.getConfiguration();
177	        Locale appLocal = getLocal(appConfig);
178	
179	        setLocal(appConfig, destLocale);
180	
181	        Utils.getApp().getResources().updateConfiguration(appConfig, appResources.getDisplayMetrics());
182	
183	        if (consumer == null) return;
184	
185	        if (isSameLocale(appLocal, destLocale)) {
186	            consumer.accept(true);
187	        } else {
188	            if (index < 20) {
189	                UtilsBridge.runOnUiThreadDelayed(new Runnable() {
190	                    @Override
191	                    public void run() {
192	                        pollCheckAppContextLocal(destLocale, index + 1, consumer);
193	                    }
194	                }, 16);
195	                return;
196	            }
197	            Log.e("LanguageUtils", "appLocal didn't update.");
198	            consumer.accept(false);
199	        }
200	    }
201	
202	    /**
203	     * If applyLanguage not work, try to call it in {@link Activity#attachBaseContext(Context)}.
204	     *
205	     * @param context The baseContext.
206	     * @return the context with language
207	     */
208	    public static Context attachBaseContext(Context context) {
209	        String spLocaleStr = UtilsBridge.getSpUtils4Utils().getString(KEY_LOCALE);
210	        if (TextUtils.isEmpty(spLocaleStr) || VALUE_FOLLOW_SYSTEM.equals(spLocaleStr)) {
211	            return context;
212	        }
213	
214	        Locale settingsLocale = string2Locale(spLocaleStr);
215	        if (settingsLocale == null) return context;
216	
217	        Resources resources = context.getResources();
218	        Configuration config = resources.getConfiguration();
219	
220	        setLocal(config, settingsLocale);
221	
222	        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1) {
223	            return context.createConfigurationContext(config);
224	        } else {
225	            resources.updateConfiguration(config, resources.getDisplayMetrics());
226	            return context;
227	        }
228	    }
229	
230	    static void applyLanguage(final Activity activity) {
231	        String spLocale = UtilsBridge.getSpUtils4Utils().getString(KEY_LOCALE);
232	        if (TextUtils.isEmpty(spLocale)) {
233	            return;
234	        }
235	
236	        Locale destLocal;
237	        if (VALUE_FOLLOW_SYSTEM.equals(spLocale)) {
238	            destLocal = getLocal(Resources.getSystem().getConfiguration());
239	        } else {
240	            destLocal = string2Locale(spLocale);
241	        }
242	
243	        if (destLocal == null) return;
244	
245	        updateConfiguration(activity, destLocal);
246	        updateConfiguration(Utils.getApp(), destLocal);
247	    }
248	
249	    private static void updateConfiguration(Context context, Locale destLocal) {
250	        Resources resources = context.getResources();
251	        Configuration config = resources.getConfiguration();
252	        setLocal(config, destLocal);
253	        resources.updateConfiguration(config, resources.getDisplayMetrics());
254	    }
255	
256	    private static String locale2String(Locale locale) {
257	        String localLanguage = locale.getLanguage(); // this may be empty
258	        String localCountry = locale.getCountry(); // this may be empty
259	        return localLanguage + "$" + localCountry;
260	    }
261	
262	    private static Locale string2Locale(String str) {
263	        Locale locale = string2LocaleReal(str);
264	        if (locale == null) {
265	            Log.e("LanguageUtils", "The string of " + str + " is not in the correct format.");
266	            UtilsBridge.getSpUtils4Utils().remove(KEY_LOCALE);
267	        }
268	        return locale;
269	    }
270	
271	    private static Locale string2LocaleReal(String str) {
272	        if (!isRightFormatLocalStr(str)) {
273	            return null;
274	        }
275	
276	        try {
277	            int splitIndex = str.indexOf("$");
278	            return new Locale(str.substring(0, splitIndex), str.substring(splitIndex + 1));
279	        } catch (Exception ignore) {
280	            return null;
281	        }
282	    }
283	
284	    private static boolean isRightFormatLocalStr(String localStr) {
285	        char[] chars = localStr.toCharArray();
286	        int count = 0;
287	        for (char c : chars) {
288	            if (c == '$') {
289	                if (count >= 1) {
290	                    return false;
291	                }
292	                ++count;
293	            }
294	        }
295	        return count == 1;
296	    }
297	
298	    private static boolean isSameLocale(Locale l0, Locale l1) {
299	        return UtilsBridge.equals(l1.getLanguage(), l0.getLanguage())
300	                && UtilsBridge.equals(l1.getCountry(), l0.getCountry());
301	    }
302	
303	    private static Locale getLocal(Configuration configuration) {
304	        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
305	            return configuration.getLocales().get(0);
306	        } else {
307	            return configuration.locale;
308	        }
309	    }
310	
311	    private static void setLocal(Configuration configuration, Locale locale) {
312	        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1) {
313	            configuration.setLocale(locale);
314	        } else {
315	            configuration.locale = locale;
316	        }
317	    }
318	}
